import { Input, Logger, Node } from 'cleo'
import { clamp, forwardYaw, num } from './SoulsMath'

/**
 * Hollow Keep — the game manager. Attach to an empty node named `GameManager` at the scene root.
 *
 * The hub of the demo. The engine has no gameplay event bus, so every gameplay object finds this node
 * once in `onStart` and talks to it through plain method calls (shared PURE helpers live in the
 * SoulsMath module instead, which every script imports):
 *
 *   enemies        registerEnemy / unregisterEnemy        (SoulsEnemy)
 *   interactables  registerInteractable / unregister...   (bonfire, pickups, lever, signs, fog gate...)
 *   spawn points   registerSpawn                          (SoulsEnemySpawn)
 *
 * UI never gets called; it POLLS public fields here and on the player every frame.
 *
 * ## What it does NOT own
 *
 * Nobody's data. Each fighter owns its own: the player its attributes, HP, stamina, flasks and the curves
 * between them (SoulsPlayer); each enemy type its stats (SoulsHollow, SoulsEliteKnight…); each weapon its
 * numbers, hitbox, moveset and damage maths (SoulsWeapon and its subclasses). Damage goes from the weapon
 * straight to the target's `receiveHit` — it never passes through here. The manager is the WORLD: who is
 * registered, where you respawn, what happens when someone dies, and the shared sounds and effects.
 *
 * ## Game flow it owns
 *
 *   rest(bonfire)          heal, refill flasks, respawn the non-boss enemies, set the respawn point
 *   onPlayerDied()         drop a bloodstain, YOU DIED, then respawnAtBonfire()
 *   startBossFight(gate)   wake the boss, show its bar, start the music
 *   onBossDefeated(boss)   dissolve the fog, banner, reward
 *
 * ## Sounds and effects
 *
 * `sfx('Swing')` plays the SoundNode of that name under the scene's `Sounds` group; `fx('Hit Spark', p)`
 * instantiates a template at a point. Both are silent no-ops when the node or template is missing, so a
 * level with no audio assigned yet plays exactly the same — just quietly. See SOULS_DEMO.md for the list.
 */
export default class SoulsGameManagerNode extends Node {
  // ----- flow -------------------------------------------------------------------------------------
  /** Seconds between the killing blow and the YOU DIED banner. */
  public deathBannerDelay: number = 1.2
  /** Seconds between the killing blow and the respawn at the bonfire. */
  public respawnDelay: number = 5
  /** Template instantiated where the player died, carrying their souls. */
  public bloodstainTemplate: string = 'Bloodstain'

  // ----- blood (see bleed) -------------------------------------------------------------------------
  /** Off, no blood at all: no spray and no decals. */
  public bloodEnabled: boolean = true
  /** Droplets thrown off a wound (particles). */
  public bloodSprayTemplate: string = 'Blood Spray'
  /** The pool decal left under a wounded body. */
  public bloodSplatTemplate: string = 'Blood Splat'
  /** The spatter decal thrown along the blow. */
  public bloodDropsTemplate: string = 'Blood Drops'
  /** Blood decals alive at once. The oldest goes first, so a long fight cannot pile up draws. */
  public maxBloodDecals: number = 24
  /** Damage that leaves a full-size splat; less shrinks it, more grows it (0.6x to 1.6x). */
  public bloodReferenceDamage: number = 120
  /** Name of the group whose SoundNode children `sfx()` plays. */
  public soundsGroup: string = 'Sounds'
  /** Name of the reward pickup revealed once the boss falls. */
  public bossRewardName: string = 'Boss Reward'
  /** Name of the lore message revealed once the boss falls. */
  public bossEpilogueName: string = 'Epilogue Message'
  /** Log a one-off warning when the project's input map lacks the souls actions. */
  public checkInputMap: boolean = true

  // ----- runtime state (read by the HUD, which reads the boss's own name and health off `boss`) ----
  public bossActive: boolean = false
  public bossDefeated: boolean = false

  private _player: Node = null
  private _hud: Node = null
  private _banner: Node = null
  private _menu: Node = null
  private _lockOn: Node = null
  private _sounds: Node = null
  private _enemies: Node[] = []
  private _interactables: Node[] = []
  private _spawns: Node[] = []
  private _bonfires: Node[] = []
  private _restBonfire: Node = null
  private _respawnPoint: number[] = null
  private _respawnYaw: number = 0
  private _bloodstain: Node = null
  private _bloodDecals: Node[] = []
  private _boss: Node = null
  private _fogGate: Node = null
  private _dying: boolean = false

  onStart() {
    this._player = this.findNode('Player')
    // Every UI belongs to someone: the player's HUD and level-up menu are the PLAYER's children, the
    // world banners (YOU DIED, BONFIRE LIT, VICTORY) are this manager's own — the game flow it runs.
    this._hud = this._player?.getChildByName('HUD')[0] ?? null
    this._menu = this._player?.getChildByName('BonfireMenu')[0] ?? null
    this._banner = this.getChildByName('Banner')[0] ?? null
    this._sounds = this.findNode(this.soundsGroup)
    if (this._player) {
      const p = this._player.worldPosition
      this._respawnPoint = [p[0], p[1], p[2]]
      const f = this._player.worldForward
      this._respawnYaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    }
    if (this.checkInputMap) this._checkInputMap()
  }

  // =================================================================================================
  // Registries
  // =================================================================================================

  public registerEnemy(enemy: Node): void { if (enemy && !this._enemies.includes(enemy)) this._enemies.push(enemy) }
  public unregisterEnemy(enemy: Node): void { this._enemies = this._enemies.filter(e => e !== enemy) }
  /** Every enemy that is spawned and not dead. */
  public liveEnemies(): Node[] { return this._enemies.filter(e => e && (e as any).spawned !== false && !(e as any).isDead) }

  public registerInteractable(node: Node): void {
    if (node && !this._interactables.includes(node)) this._interactables.push(node)
    if (node && (node as any).isBonfire && !this._bonfires.includes(node)) this._bonfires.push(node)
    if (node && (node as any).isFogGate) this._fogGate = node
  }
  public unregisterInteractable(node: Node): void { this._interactables = this._interactables.filter(n => n !== node) }
  public interactables(): Node[] { return this._interactables }

  public registerSpawn(spawn: Node): void { if (spawn && !this._spawns.includes(spawn)) this._spawns.push(spawn) }

  public get player(): Node { return this._player }
  public get boss(): Node { return this._boss }

  // =================================================================================================
  // Zones (the player's trigger overlaps, forwarded by SoulsPlayer)
  // =================================================================================================

  /** The player walked into a trigger zone. The boss arena's zone starts the fight. */
  public onPlayerEnteredZone(zone: Node): void {
    if (!zone || !(zone as any).getVariable?.('isBossArena')) return
    const player = this._player as any
    if (!this.bossActive && !this.bossDefeated && player && !player.isDead) this.startBossFight(this._fogGate)
  }

  /** The player left a trigger zone. Leaving a message's zone closes the message it opened. */
  public onPlayerLeftZone(zone: Node): void {
    const hud = this._hud as any
    hud?.closeMessageFrom?.(zone)
  }

  public awardSouls(amount: number): void {
    const player = this._player as any
    if (player?.addSouls) player.addSouls(amount)
  }

  /** An enemy reached 0 HP. Bosses route on to `onBossDefeated`. */
  public onEnemyKilled(enemy: Node): void {
    const e = enemy as any
    this.awardSouls(num(e.soulsReward, 0))
    this._lockOnNode()?.onTargetDied?.(enemy)
    if (e.isBoss) this.onBossDefeated(enemy)
  }

  // =================================================================================================
  // Bonfires, death and respawn
  // =================================================================================================

  public lightBonfire(bonfire: Node): void {
    this.showBanner('BONFIRE LIT', 'gold')
    this.sfx('Bonfire Lit')
    this._setRespawn(bonfire)
  }

  /**
   * Rest at a bonfire: the souls checkpoint. Heals and refills, respawns every enemy that is not a
   * defeated boss, makes this bonfire the respawn point, and opens the level-up menu.
   */
  public rest(bonfire: Node): void {
    const player = this._player as any
    if (!player) return
    this._setRespawn(bonfire)
    player.restoreAll?.()
    this.respawnEnemies(false)
    this._lockOnNode()?.unlock?.()
    this.sfx('Rest')
    ;(this._menu as any)?.open?.(this, player, bonfire)
  }

  /** Called by the menu when the player stands up again. */
  public leaveBonfire(): void {
    (this._player as any)?.standUp?.()
  }

  public onPlayerDied(player: Node): void {
    if (this._dying) return
    this._dying = true
    const p = player as any
    this._lockOnNode()?.unlock?.()

    // The souls go into the ground where you fell — at the last SAFE spot if you fell off the world.
    const at = p.lastSafePosition ?? player.worldPosition
    this.dropBloodstain(at, num(p.souls, 0))
    p.souls = 0

    this.after(this.deathBannerDelay, () => {
      this.showBanner('YOU DIED', 'red')
      this.sfx('Death')
    })
    this.after(this.respawnDelay, () => this.respawnAtBonfire())
  }

  /** A new stain replaces the old one, and the souls in the old one are gone for good. */
  public dropBloodstain(at: ArrayLike<number>, souls: number): void {
    if (this._bloodstain) {
      try { this._bloodstain.remove() } catch { /* already gone */ }
      this._bloodstain = null
    }
    if (souls <= 0) return
    const stain = this.scene?.instantiate(this.bloodstainTemplate, { position: [at[0], at[1], at[2]] })
    if (!stain) return
    ;(stain as any).souls = souls
    this._bloodstain = stain
  }

  /** The stain was touched. Clears our handle so a later death does not try to remove it. */
  public onBloodstainRecovered(stain: Node): void {
    if (this._bloodstain === stain) this._bloodstain = null
  }

  public get bloodstain(): Node { return this._bloodstain }

  public respawnAtBonfire(): void {
    const player = this._player as any
    this._dying = false
    if (!player) return
    this._resetBossFight()
    this.respawnEnemies(false)
    const at = this._respawnPoint ?? [0, 0, 0]
    player.respawnAt?.(at, this._respawnYaw)
    ;(this._banner as any)?.hideBanner?.()
  }

  /** Re-create every enemy from its spawn point. Bosses only when `includeBoss` — never a defeated one. */
  public respawnEnemies(includeBoss: boolean): void {
    for (const spawn of this._spawns) {
      const s = spawn as any
      if (s.isBossSpawn && (!includeBoss || this.bossDefeated)) continue
      s.respawnEnemy?.()
    }
  }

  private _setRespawn(bonfire: Node): void {
    if (!bonfire) return
    this._restBonfire = bonfire
    const b = bonfire as any
    const point: Node = b.respawnPoint?.() ?? bonfire
    const p = point.worldPosition
    this._respawnPoint = [p[0], p[1] + 0.1, p[2]]
    this._respawnYaw = forwardYaw(point)
  }

  // =================================================================================================
  // The boss
  // =================================================================================================

  /** The boss spawn calls this every time it creates a boss, so the manager always holds the live one. */
  public registerBoss(boss: Node): void {
    this._boss = boss
  }

  public startBossFight(gate: Node): void {
    if (this.bossActive || this.bossDefeated) return
    if (gate) this._fogGate = gate
    const boss = this._boss as any
    if (!boss || boss.isDead) return
    this.bossActive = true
    boss.awaken?.()
    this._music('Boss Music', true)
    this._music('Ambience', false)
  }

  public onBossDefeated(boss: Node): void {
    this.bossDefeated = true
    this.bossActive = false
    this._music('Boss Music', false)
    this._music('Ambience', true)
    ;(this._fogGate as any)?.dissolve?.()
    this.after(2.5, () => {
      this.showBanner('VICTORY ACHIEVED', 'gold')
      this.sfx('Victory')
    })
    for (const name of [this.bossRewardName, this.bossEpilogueName]) {
      const node = this.findNode(name) as any
      if (node?.reveal) node.reveal()
    }
  }

  /** The player died mid-fight: the boss goes back to sleep at full health and the fog lets you in again. */
  private _resetBossFight(): void {
    if (this.bossDefeated) return
    const wasActive = this.bossActive
    this.bossActive = false
    if (wasActive) {
      this._music('Boss Music', false)
      this._music('Ambience', true)
    }
    ;(this._fogGate as any)?.resetGate?.()
    this.respawnEnemies(true)
  }

  // =================================================================================================
  // Presentation helpers
  // =================================================================================================

  public showBanner(text: string, kind: string): void {
    const banner = this._banner as any
    if (banner?.showBanner) banner.showBanner(text, kind)
  }

  /** A short line under the HUD prompt: "Picked up Estus Shard", "Opens from the other side". */
  public notice(text: string): void {
    const hud = this._hud as any
    if (hud?.showNotice) hud.showNotice(text)
  }

  /** Show a readable message (title + body) until the player walks away or presses Interact again. */
  public showMessage(title: string, body: string, source: Node): void {
    const hud = this._hud as any
    if (hud?.showMessage) hud.showMessage(title, body, source)
  }

  /** Play the SoundNode of this name under the Sounds group. Silent when there is none. */
  public sfx(name: string): void {
    const node = this._soundNamed(name) as any
    if (node?.play) node.play()
  }

  /** Instantiate an effect template at a world point. Silent when the template does not exist. */
  public fx(template: string, at: ArrayLike<number>): Node {
    if (!template) return null
    return this.scene?.instantiate(template, { position: [at[0], at[1], at[2]] }) ?? null
  }

  /**
   * A hit drew blood: droplets fly off `target`, a pool lands under it and a spatter along the blow,
   * from `from` toward `target`. Called by SoulsCharacter.receiveHit when a hit lands. `amount` (the damage dealt) sizes the splat.
   */
  public bleed(target: Node, from: Node, amount: number): void {
    if (!this.bloodEnabled || !target || !(amount > 0)) return
    const at = target.worldPosition
    const src = from?.worldPosition
    let dx = src ? at[0] - src[0] : 0
    let dz = src ? at[2] - src[2] : 1
    const len = Math.hypot(dx, dz)
    if (len < 1e-4) { dx = 0; dz = 1 } else { dx /= len; dz /= len }
    const t = target as any
    const height = num(t.bodyHeight, 1.8)
    const scale = clamp(amount / Math.max(1, this.bloodReferenceDamage), 0.6, 1.6)

    this.fx(this.bloodSprayTemplate, [at[0], at[1] + height * 0.6, at[2]])
    // Spawned a little above the ground: each decal finds the floor itself (SoulsBloodSplat).
    this._splat(this.bloodSplatTemplate, [at[0], at[1] + 0.5, at[2]], NaN, scale)
    this._splat(this.bloodDropsTemplate, [at[0] + dx * 0.9 * scale, at[1] + 0.5, at[2] + dz * 0.9 * scale],
                Math.atan2(dx, dz) * 180 / Math.PI, scale)
  }

  /** The blood decals currently on the ground, oldest first. */
  public get bloodDecals(): readonly Node[] { return this._bloodDecals }

  private _splat(template: string, at: number[], yaw: number, scale: number): void {
    if (!template) return
    const splat = this.scene?.instantiate(template, { position: at }) as any
    if (!splat) return
    splat.yaw = yaw
    splat.sizeScale = scale
    // Splats remove themselves when they fade out; forget those, then retire the oldest past the cap.
    this._bloodDecals = this._bloodDecals.filter(d => !!d.scene)
    this._bloodDecals.push(splat)
    while (this._bloodDecals.length > Math.max(0, this.maxBloodDecals)) {
      const old = this._bloodDecals.shift()
      try { old.remove() } catch { /* already gone */ }
    }
  }

  /** Shake the player's camera. 0.2 is a hit, 0.6 a boss slam. */
  public shake(amount: number): void {
    const rig = this._lockOnNode() as any
    if (rig?.shake) rig.shake(amount)
  }

  private _music(name: string, on: boolean): void {
    const node = this._soundNamed(name) as any
    if (!node) return
    if (on) node.play?.()
    else node.stop?.()
  }

  private _soundNamed(name: string): Node {
    if (!this._sounds) return null
    return this._sounds.getChildByName(name)[0] ?? null
  }

  private _lockOnNode(): any {
    if (!this._lockOn && this._player) {
      this._lockOn = this._player.children.find(c => c.nodeType === 'cameraRig') ?? null
    }
    return this._lockOn
  }

  private _checkInputMap(): void {
    const map: any = (Input as any).map
    const names = new Set<string>()
    for (const m of map?.maps ?? []) for (const a of m.actions ?? []) names.add(a.name)
    const missing = ['LightAttack', 'HeavyAttack', 'Roll', 'LockOn', 'UseItem', 'SwapWeapon', 'Interact']
      .filter(n => !names.has(n))
    if (missing.length) {
      Logger.warn('Hollow Keep: the input map has no ' + missing.join(', ') + ' action(s). Import the '
        + 'example again, or add them in the Input panel — see SOULS_DEMO.md "Controls".', 'Script')
    }
  }
}

import { Input, Logger, ModelNode, Node, moveWorldDirection, setMoveWorld } from 'cleo'
import { clamp, num } from './SoulsMath'
import { Swing, bladeCapsule, closeSwing, newSwing, openSwing, stepSwing, wieldedBy } from './SoulsHitbox'
import SoulsCharacterNode from './SoulsCharacter'

/**
 * Hollow Keep — the player. Attach to the `Player` root, which must be a Character node. Extends
 * SoulsCharacter, so its health, defence, hit handling and weapons work exactly as an enemy's do.
 *
 * Expected hierarchy (names matter where marked *):
 *
 *   Player                   Character (this script) — capsule body, friction 0
 *   ├── camera rig           CameraRigNode + SoulsLockOn — must come BEFORE the controller
 *   │   └── camera
 *   ├── <model>              the skinned model; found automatically (first Model child with an animator)
 *   ├── Weapons *            empty group; the weapons in `weaponTemplates` are spawned into it on start
 *   └── Player Controller    ControllerNode, source Player, LAST child; Jump and Sprint actions blank
 *
 * ## What the controller does, and what this does
 *
 * The controller turns Move and Look into a camera-relative intent every frame. This script runs after it
 * (a character's `onUpdate` precedes its locomotion) and PATCHES that intent: it decides the speed, the
 * facing mode and — during a roll, a lunge or a stagger — replaces the movement outright. Locomotion then
 * turns the result into velocity. Nothing here ever writes `velocity`, except the one-off zero on respawn.
 *
 * ## The action state machine
 *
 *   free ──LightAttack/HeavyAttack──▶ attack ──combo window + buffered press──▶ attack (next move)
 *     │  ──Roll (tap)──────────────▶ roll / backstep (no stick)
 *     │  ──UseItem─────────────────▶ drink
 *     │  ──SwapWeapon──────────────▶ swap
 *     │  ──Interact────────────────▶ (whatever the interactable asks for: rest, fog, gesture)
 *   any ──hit outside i-frames─────▶ hit ──▶ free
 *   any ──HP 0─────────────────────▶ dead ──respawn──▶ free
 *
 * ## Stats belong to the player
 *
 * The four attributes, and the curves that turn them into HP, stamina and a level (`hpForVigor`,
 * `staminaForEndurance`, `levelFor`, `levelCost`), are this script's own. The weapon in hand turns
 * STR/DEX into damage (SoulsWeapon.attackRating). Nothing about the player lives on the manager.
 *
 * Presses are BUFFERED for `inputBufferSeconds`, so mashing during an attack queues the next one instead
 * of being lost — the single most important thing for the controls to feel right.
 *
 * ## Animation contract
 *
 * One-shots (attacks, roll, drink...) play through `animator.playAction`, as full-body actions over the
 * locomotion machine. The machine itself needs only `Died` and `Revive` triggers. Attack timing comes
 * from CLIP EVENTS named `hit`, `combo` and `recover` (and `drink` on the drink clip); a clip without them
 * falls back to the move's `hitTime`/`comboTime`/`recoverTime`, so a freshly imported clip still works
 * before anyone has authored its markers. Action slots ignore root motion — clips must be IN PLACE; the
 * travel of a roll or a lunge is driven from here.
 */
export default class SoulsPlayerNode extends SoulsCharacterNode {
  public displayName: string = 'Player'
  public team: string = 'player'
  /** The weapons the player starts with, by template. F swaps between them. */
  public weaponTemplates: string = 'Straight Sword, Greatsword'

  // ----- stats (level-up spends souls on these four) ---------------------------------------------
  public vigor: number = 10
  public endurance: number = 10
  public strength: number = 10
  public dexterity: number = 10
  public souls: number = 0

  // ----- resources (runtime; the HUD reads them) --------------------------------------------------
  public hp: number = 400
  public maxHp: number = 400
  public bodyRadius: number = 0.3
  public stamina: number = 90
  public maxStamina: number = 90
  public estus: number = 3
  public estusMax: number = 3
  /** HP restored per flask, spread over `estusHealSeconds`. */
  public estusHeal: number = 250
  public estusHealSeconds: number = 0.4

  // ----- stat curves (see hpForVigor and friends) -------------------------------------------------
  /** HP at Vigor 10. Each point to 30 adds `hpPerVigor`, then the curve flattens. */
  public baseHp: number = 400
  public hpPerVigor: number = 30
  /** Stamina at Endurance 10, plus `staminaPerEndurance` per point to 40. */
  public baseStamina: number = 90
  public staminaPerEndurance: number = 3

  // ----- movement -------------------------------------------------------------------------------
  public jogSpeed: number = 3.8
  public sprintSpeed: number = 5.8
  /** Throttle while locked on: strafing is slower than running. */
  public lockedSpeedScale: number = 0.8
  /** Ramp while freely moving. Actions snap (0) so a roll starts at full speed. */
  public freeAcceleration: number = 24
  /** Degrees per second the body turns toward a locked target while standing. */
  public lockTurnSpeed: number = 540

  // ----- stamina --------------------------------------------------------------------------------
  public staminaRegen: number = 45
  public staminaRegenDelay: number = 0.6
  public sprintCostPerSecond: number = 14
  /** After sprinting to empty, sprint stays locked until stamina recovers to this. */
  public exhaustThreshold: number = 15

  // ----- roll / backstep --------------------------------------------------------------------------
  public rollCost: number = 20
  public rollSeconds: number = 0.7
  public rollInvulnStart: number = 0.06
  public rollInvulnEnd: number = 0.42
  public rollSpeed: number = 6.5
  public rollFastSeconds: number = 0.45
  public rollSlowSpeed: number = 2
  public backstepCost: number = 12
  public backstepSeconds: number = 0.45
  public backstepInvulnEnd: number = 0.22
  public backstepSpeed: number = 4
  public backstepMoveSeconds: number = 0.25
  /** Hold Roll longer than this while moving and it becomes a sprint instead of a roll. */
  public sprintHoldSeconds: number = 0.25

  // ----- input / reactions ------------------------------------------------------------------------
  public inputBufferSeconds: number = 0.3
  /** A hit at or above this much damage is a heavy stagger with knockback; below, a flinch. */
  public heavyHitThreshold: number = 150
  public hitLightSeconds: number = 0.45
  /** A swing that meets a wall (a `blocksSwings` body) before any enemy bounces off it for this long. */
  public recoilSeconds: number = 0.45
  public hitHeavySeconds: number = 0.9
  public knockbackSpeed: number = 4
  public knockbackSeconds: number = 0.15
  /** Falling below this height is death. */
  public killY: number = -15

  // ----- clip names (swap these when the final animations arrive) ---------------------------------
  public rollClip: string = 'Souls_Roll'
  public backstepClip: string = 'Souls_Backstep'
  public drinkClip: string = 'Souls_Drink'
  /** Fallback seconds into the drink clip at which the heal starts when it has no `drink` event. */
  public drinkTime: number = 0.85
  public hitLightClip: string = 'Souls_HitLight'
  public hitHeavyClip: string = 'Souls_HitHeavy'
  /** Played when a swing bounces off a wall. */
  public recoilClip: string = 'Souls_HitLight'
  public swapClip: string = 'Souls_Swap'
  public restClip: string = 'Souls_Rest'
  public fogWalkClip: string = 'Souls_FogWalk'

  // ----- derived, read by the HUD and other scripts ------------------------------------------------
  public level: number = 1
  /** I-frames (roll, backstep, fog, rest, death): `hurtboxActive` is its inverse. */
  public invulnerable: boolean = false
  public actionState: string = 'free'
  public isSprinting: boolean = false
  public attackRatingNow: number = 0
  /** What pressing Interact would do right now, or '' — the HUD prompt. */
  public interactPrompt: string = ''
  /** The last souls gain and how long ago, for the HUD popup. */
  public lastSoulsGain: number = 0
  public soulsGainAge: number = 99
  /** Where the bloodstain goes if the player falls off the world. */
  public lastSafePosition: number[] = null

  private _model: ModelNode = null
  private _rig: Node = null
  private _offEvents: (() => void) | null = null

  private _stateTime: number = 0
  private _bufferAction: string = ''
  private _bufferAge: number = 99
  private _rollHeld: number = -1
  private _sprintedThisHold: boolean = false
  private _sinceSpend: number = 99
  private _sprintLocked: boolean = false
  private _safeTimer: number = 0

  // the current action
  private _move: any = null
  private _clip: string = ''
  private _clipLength: number = 0
  private _playSpeed: number = 1
  /** The active window has opened this attack (the swing has started connecting). */
  private _windowOpened: boolean = false
  private _swing: Swing = newSwing()
  private _comboOpen: boolean = false
  private _recovered: boolean = false
  private _usesEvents: boolean = false
  private _motionDir: number[] = [0, 0, 1]
  private _actionSeconds: number = 0
  private _healLeft: number = 0
  private _healRate: number = 0
  private _drank: boolean = false
  private _swapped: boolean = false
  private _gestureSeconds: number = 0
  private _fogSpeed: number = 0
  private _interactTarget: Node = null
  /** Interactables whose trigger zone the player is standing in. See onTriggerEnter. */
  private _nearby: Node[] = []

  onStart() {
    this.setVariable('isPlayer', true, 'boolean', 'public')
    this._gm = this.findNode('GameManager')
    this._model = this._findModel()
    this._rig = this.children.find(c => c.nodeType === 'cameraRig') ?? null
    this._spawnWeapons()

    this.recomputeStats()
    this.hp = this.maxHp
    this.stamina = this.maxStamina
    this.estus = this.estusMax
    const p = this.worldPosition
    this.lastSafePosition = [p[0], p[1], p[2]]

    const animator = this._model?.animator as any
    // The character's idle/locomotion/death machine is embedded in its model node. A model swapped by
    // deleting the node and dropping a new one in has none, and would walk around in its bind pose with
    // nothing to say why. Linking the mannequin rig gives it the "Souls Character" controller.
    const machine = animator?.getStateMachine?.()
    if (animator && !machine?.states?.length)
      Logger.warn('Hollow Keep: "' + this.name + '" has no animation controller on its model, so it will hold its bind pose. '
        + 'Select the model node and assign "Souls Character" in its Animation section (or link the mannequin rig).', 'Script')
    if (animator?.onAnimationEvent) {
      this._offEvents = animator.onAnimationEvent((name: string, clip: string) => this._onAnimEvent(name, clip))
    }
  }

  onDespawn() {
    this._offEvents?.()
    this._offEvents = null
  }

  // =================================================================================================
  // Public API (called by the manager, enemies, interactables and the menu)
  // =================================================================================================

  // ----- stat curves: pure functions of their arguments and the tuning fields above ------------------

  /** Max HP for a Vigor value. Steep to 30, gentler to 40, then a trickle. */
  public hpForVigor(vigor: number): number {
    const v = Math.max(10, vigor)
    return Math.round(this.baseHp + this.hpPerVigor * Math.min(v - 10, 20)
      + 12 * clamp(v - 30, 0, 10) + 5 * Math.max(v - 40, 0))
  }

  /** Max stamina for an Endurance value. */
  public staminaForEndurance(endurance: number): number {
    const e = Math.max(10, endurance)
    return Math.round(this.baseStamina + this.staminaPerEndurance * Math.min(e - 10, 30) + Math.max(e - 40, 0))
  }

  /** Souls needed to go from `level` to `level + 1`. */
  public levelCost(level: number): number {
    const l = Math.max(1, level) - 1
    return Math.round(400 + 120 * l + 4 * l * l)
  }

  /** Character level from the four stats: 1 + every point spent above 10. */
  public levelFor(vigor: number, endurance: number, strength: number, dexterity: number): number {
    return 1 + (vigor - 10) + (endurance - 10) + (strength - 10) + (dexterity - 10)
  }

  /** Max HP / stamina / level from the four stats, and the held weapon's attack rating. */
  public recomputeStats(): void {
    this.maxHp = this.hpForVigor(this.vigor)
    this.maxStamina = this.staminaForEndurance(this.endurance)
    this.level = this.levelFor(this.vigor, this.endurance, this.strength, this.dexterity)
    const weapon = this.currentWeapon() as any
    this.attackRatingNow = weapon?.attackRating ? weapon.attackRating(this.strength, this.dexterity) : 0
    this.hp = Math.min(this.hp, this.maxHp)
    this.stamina = Math.min(this.stamina, this.maxStamina)
  }

  // ----- taking hits (SoulsCharacter.receiveHit calls these) -----------------------------------------

  /** I-frames make a hit pass straight through, so a bolt keeps flying past a rolling player. */
  protected _canBeHit(damage: number): boolean {
    return !this.isDead && !this.invulnerable && damage > 0
  }

  protected _onHurt(dealt: number, from: Node): void {
    ;(this._gm as any)?.sfx?.('Player Hurt')
  }

  /** Interrupt whatever was happening — a drink included, which is the souls tax on greedy healing. */
  protected _onDamaged(dealt: number, poiseDamage: number, from: Node): void {
    const heavy = dealt >= this.heavyHitThreshold
    this._stopAction()
    this._motionDir = from ? this._dirFrom(from.worldPosition) : this._forward(-1)
    this._enter('hit')
    this._actionSeconds = heavy ? this.hitHeavySeconds : this.hitLightSeconds
    this._play(heavy ? this.hitHeavyClip : this.hitLightClip, 1)
    ;(this._gm as any)?.shake?.(heavy ? 0.35 : 0.15)
  }

  /** A flask shard: one more flask, and every flask refilled. */
  public addEstusFlask(): void {
    this.estusMax += 1
    this.estus = this.estusMax
  }

  /** Refill up to `count` flasks, never past the maximum. */
  public refillEstus(count: number): void {
    this.estus = Math.min(this.estusMax, this.estus + Math.max(1, Math.round(count)))
  }

  public addSouls(amount: number): void {
    if (amount <= 0) return
    this.souls += Math.round(amount)
    this.lastSoulsGain = Math.round(amount)
    this.soulsGainAge = 0
    ;(this._gm as any)?.sfx?.('Souls')
  }

  /** Full heal, full stamina, full flasks. Resting and respawning both do this. */
  public restoreAll(): void {
    this.recomputeStats()
    this.hp = this.maxHp
    this.stamina = this.maxStamina
    this.estus = this.estusMax
    this._healLeft = 0
  }

  /** Spend souls on a set of stats. The menu validates first; this re-validates. */
  public applyLevelUp(vigor: number, endurance: number, strength: number, dexterity: number, cost: number): boolean {
    if (cost > this.souls) return false
    if (vigor < this.vigor || endurance < this.endurance || strength < this.strength || dexterity < this.dexterity) return false
    this.souls -= cost
    this.vigor = vigor
    this.endurance = endurance
    this.strength = strength
    this.dexterity = dexterity
    this.restoreAll()
    return true
  }

  /** Back to life at a point. Called by the manager after YOU DIED. */
  public respawnAt(at: ArrayLike<number>, yaw: number): void {
    this._stopAction()
    this.isDead = false
    this.restoreAll()
    this.setPosition([at[0], at[1], at[2]])
    this.setRotation([0, yaw, 0])
    this.velocity = [0, 0, 0]
    this.lastSafePosition = [at[0], at[1], at[2]]
    this._bufferAction = ''
    this._enter('free')
    const animator = this._model?.animator as any
    animator?.resetTrigger?.('Died')
    animator?.setTrigger?.('Revive')
    const rig = this._rig as any
    rig?.setOrbit?.(yaw, 12)
    rig?.snapToTarget?.()
  }

  /** Called by a bonfire: sit down. The manager opens the menu; `standUp` ends it. */
  public sitAtBonfire(): void {
    this._stopAction()
    this._enter('rest')
    this._play(this.restClip, 1, true)
  }

  public standUp(): void {
    if (this.actionState !== 'rest') return
    this._stopAction()
    this._enter('free')
  }

  /**
   * Called by the fog gate: stand at `start` facing `yaw`, then walk `distance` metres over `seconds`
   * with i-frames. The gate turns its own collider off for the duration.
   */
  public walkThroughFog(start: ArrayLike<number>, yaw: number, distance: number, seconds: number): void {
    this._stopAction()
    this.setPosition([start[0], start[1], start[2]])
    this.setRotation([0, yaw, 0])
    this._motionDir = [Math.sin(yaw * Math.PI / 180), 0, Math.cos(yaw * Math.PI / 180)]
    this._fogSpeed = distance / Math.max(0.1, seconds)
    this._enter('fog')
    this._actionSeconds = seconds
    this._play(this.fogWalkClip, 1)
  }

  /** A short locked gesture (picking something up, pulling a lever). */
  public playGesture(clip: string, seconds: number): void {
    if (this.isDead) return
    this._stopAction()
    this._enter('gesture')
    this._actionSeconds = seconds
    if (clip) this._play(clip, 1)
  }

  /** The lock-on target's node, or null. Read off the camera rig's SoulsLockOn. */
  public get lockTarget(): Node {
    return (this._rig as any)?.lockTarget ?? null
  }

  // =================================================================================================
  // The frame
  // =================================================================================================

  onUpdate(delta: number) {
    const intent = this.drive()
    this._stateTime += delta
    this._bufferAge += delta
    this._sinceSpend += delta
    this.soulsGainAge += delta

    if (this.isDead) { this._holdStill(intent); return }

    if (this.worldPosition[1] < this.killY) {
      this.hp = 0
      this._die()
      this._holdStill(intent)
      return
    }

    this._trackSafeGround(delta)
    this._tickHeal(delta)
    this._readInput()
    this._findInteractable()

    switch (this.actionState) {
      case 'free': this._free(intent, delta); break
      case 'attack': this._attack(intent, delta); break
      case 'roll': this._roll(intent); break
      case 'backstep': this._backstep(intent); break
      case 'drink': this._drink(intent); break
      case 'swap': this._swap(intent); break
      case 'hit': this._hit(intent); break
      case 'recoil': this._hit(intent); break
      case 'rest': this._holdStill(intent); break
      case 'gesture':
        this._holdStill(intent)
        if (this._stateTime >= this._actionSeconds) this._enter('free')
        break
      case 'fog':
        this._driveMotion(intent, this._motionDir, this._fogSpeed)
        if (this._stateTime >= this._actionSeconds) this._enter('free')
        break
      default: this._enter('free')
    }

    this.invulnerable = this._computeInvulnerable()
    this.hurtboxActive = !this.invulnerable
    this._tickStamina(delta)
  }

  // ----- states ----------------------------------------------------------------------------------

  private _free(intent: any, delta: number): void {
    const target = this.lockTarget
    const moving = Math.hypot(intent.move[0], intent.move[1]) > 0.15

    // Sprint: Roll HELD past the threshold while moving, with stamina to burn.
    const holdSprint = this._rollHeld >= this.sprintHoldSeconds && moving
    if (this.stamina <= 0) this._sprintLocked = true
    if (this._sprintLocked && this.stamina >= this.exhaustThreshold) this._sprintLocked = false
    this.isSprinting = holdSprint && !this._sprintLocked

    this.acceleration = this.freeAcceleration
    this.walkSpeed = this.jogSpeed
    this.runSpeed = this.sprintSpeed
    intent.sprint = this.isSprinting
    if (this.isSprinting) {
      this.stamina = Math.max(0, this.stamina - this.sprintCostPerSecond * delta)
      this._sinceSpend = 0
    }

    if (target && !this.isSprinting) {
      // Strafe: face the target, move relative to the camera (which is aimed at it).
      this.facingMode = 'aim'
      intent.speedScale = this.lockedSpeedScale
      if (!moving) this._turnToward(target.worldPosition, this.lockTurnSpeed * delta)
    } else {
      this.facingMode = 'velocity'
      intent.speedScale = 1
    }

    // Buffered actions, most recent first.
    if (this._bufferAge > this.inputBufferSeconds) this._bufferAction = ''
    const action = this._bufferAction
    if (!action) return
    if (action === 'light' || action === 'heavy') this._startAttack(action === 'light' ? 'light' : 'heavy', null)
    else if (action === 'roll') this._startRoll(intent)
    else if (action === 'item') this._startDrink()
    else if (action === 'swap') this._startSwap()
    else if (action === 'interact') this._interact()
  }

  private _attack(intent: any, delta: number): void {
    const move = this._move
    const t = this._stateTime * this._playSpeed   // clip seconds

    // Fallback timing for clips that carry no events.
    if (!this._usesEvents && move) {
      const hitTime = num(move.hitTime, 0.4)
      if (!this._windowOpened && t >= hitTime) this._openWindow()
      if (this._swing.open && t >= hitTime + num(move.activeSeconds, 0.15)) closeSwing(this._swing)
      if (!this._comboOpen && t >= num(move.comboTime, 0.5)) this._comboOpen = true
      if (!this._recovered && t >= num(move.recoverTime, 0.7)) this._recovered = true
    }
    if (this._swing.open && this._stepSwing()) return

    // Track toward the target (or the stick) only during the wind-up.
    if (this._stateTime < num(move?.trackSeconds, 0.2)) {
      const target = this.lockTarget
      if (target) this._turnToward(target.worldPosition, 720 * delta)
      else {
        const stick = moveWorldDirection([0, 0, 0] as any, intent)
        if (Math.hypot(stick[0], stick[2]) > 0.2) this._turnToward(
          [this.worldPosition[0] + stick[0], 0, this.worldPosition[2] + stick[2]], 720 * delta)
      }
    }

    // Lunge: forward drive for a window of the clip.
    const lungeStart = num(move?.lungeStart, 0)
    const lunging = t >= lungeStart && t < lungeStart + num(move?.lungeSeconds, 0) * this._playSpeed
    this._driveMotion(intent, this._forward(1), lunging ? num(move?.lungeSpeed, 0) : 0)

    // Chain: inside the combo window, a buffered attack goes straight to the next move.
    const buffered = this._bufferAge <= this.inputBufferSeconds ? this._bufferAction : ''
    if (this._comboOpen && this._windowOpened && (buffered === 'light' || buffered === 'heavy')) {
      const next = buffered === 'light' ? (move?.next || '') : ''
      this._startAttack(buffered, next)
      return
    }
    // After recovery, a roll or a drink cancels the tail.
    if (this._recovered && (buffered === 'roll' || buffered === 'item')) {
      this._enter('free')
      return
    }
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  private _roll(intent: any): void {
    const t = this._stateTime
    const speed = t < this.rollFastSeconds ? this.rollSpeed : (t < this.rollSeconds * 0.85 ? this.rollSlowSpeed : 0)
    this._driveMotion(intent, this._motionDir, speed)
    if (t >= this.rollSeconds) this._enter('free')
  }

  private _backstep(intent: any): void {
    const t = this._stateTime
    this._driveMotion(intent, this._motionDir, t < this.backstepMoveSeconds ? this.backstepSpeed : 0)
    if (t >= this.backstepSeconds) this._enter('free')
  }

  private _drink(intent: any): void {
    this._holdStill(intent)
    const t = this._stateTime
    if (!this._drank && !this._usesEvents && t >= this.drinkTime) this._doDrink()
    if (t >= this._actionSeconds) this._enter('free')
  }

  private _swap(intent: any): void {
    this._holdStill(intent)
    if (!this._swapped && this._stateTime >= this._actionSeconds * 0.5) {
      this._swapped = true
      this.equipWeapon((this._weaponIndex + 1) % Math.max(1, this._weapons.length))
      this.recomputeStats()
    }
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  private _hit(intent: any): void {
    this._driveMotion(intent, this._motionDir, this._stateTime < this.knockbackSeconds ? this.knockbackSpeed : 0)
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  // ----- entering actions ------------------------------------------------------------------------

  /** Start an attack. `kind` light/heavy; `named` is the next combo move, or null for the chain's start. */
  private _startAttack(kind: string, named: string): void {
    if (this.stamina <= 0) return
    const weapon = this.currentWeapon() as any
    if (!weapon) return
    const name = named || (kind === 'heavy' ? weapon.heavyMove : weapon.lightMove)
    const move = weapon.findMove?.(name) ?? weapon.findMove?.(weapon.lightMove)
    if (!move) return
    this._consumeBuffer()
    this._spend(num(move.staminaCost, 20) * num(weapon.staminaMul, 1))

    this._move = move
    this._windowOpened = false
    closeSwing(this._swing)
    this._comboOpen = false
    this._recovered = false
    this._enter('attack')
    this._playSpeed = Math.max(0.05, num(move.playSpeed, 1))
    this._play(move.clip, this._playSpeed)
    this._usesEvents = this._clipHasEvent(move.clip, 'hit')
    const length = this._clipLength > 0 ? this._clipLength : num(move.recoverTime, 0.7) + 0.4
    this._actionSeconds = length / this._playSpeed
    ;(this._gm as any)?.sfx?.(kind === 'heavy' ? 'Swing Heavy' : 'Swing')
  }

  private _startRoll(intent: any): void {
    if (this.stamina <= 0) return
    this._consumeBuffer()
    const dir = moveWorldDirection([0, 0, 0] as any, intent)
    const len = Math.hypot(dir[0], dir[2])
    if (len < 0.2) {
      // No stick: a backstep, facing kept.
      this._spend(this.backstepCost)
      this._motionDir = this._forward(-1)
      this._enter('backstep')
      this._play(this.backstepClip, 1)
    } else {
      this._spend(this.rollCost)
      this._motionDir = [dir[0] / len, 0, dir[2] / len]
      this.setRotation([0, Math.atan2(dir[0], dir[2]) * 180 / Math.PI, 0])
      this._enter('roll')
      this._play(this.rollClip, 1)
    }
    ;(this._gm as any)?.sfx?.('Roll')
  }

  private _startDrink(): void {
    this._consumeBuffer()
    if (this.estus <= 0) {
      ;(this._gm as any)?.notice?.('No Estus left')
      return
    }
    this._drank = false
    this._enter('drink')
    this._play(this.drinkClip, 1)
    this._usesEvents = this._clipHasEvent(this.drinkClip, 'drink')
    this._actionSeconds = this._clipLength > 0 ? this._clipLength : 1.4
  }

  private _startSwap(): void {
    this._consumeBuffer()
    if (this._weapons.length < 2) return
    this._swapped = false
    this._enter('swap')
    this._play(this.swapClip, 1)
    this._actionSeconds = this._clipLength > 0 ? this._clipLength : 0.4
  }

  private _interact(): void {
    this._consumeBuffer()
    const target = this._interactTarget as any
    if (!target?.interact) return
    try { target.interact(this) }
    catch (e) { Logger.warn('Hollow Keep: interact failed on ' + (this._interactTarget?.name ?? '?') + ': ' + e, 'Script') }
  }

  protected _die(): void {
    if (this.isDead) return
    this.isDead = true
    this._stopAction()
    this._enter('dead')
    ;(this._model?.animator as any)?.setTrigger?.('Died')
    ;(this._gm as any)?.onPlayerDied?.(this)
  }

  // ----- events ----------------------------------------------------------------------------------

  private _onAnimEvent(name: string, clip: string): void {
    if (clip && this._clip && clip !== this._clip) return
    if (this.actionState === 'attack') {
      if (name === 'hit' && !this._windowOpened) this._openWindow()
      else if (name === 'hitEnd') closeSwing(this._swing)
      else if (name === 'combo') this._comboOpen = true
      else if (name === 'recover') this._recovered = true
    } else if (this.actionState === 'drink' && name === 'drink' && !this._drank) {
      this._doDrink()
    }
  }

  /** The `hit` event: the blade starts connecting. It stays live until `hitEnd`. */
  private _openWindow(): void {
    this._windowOpened = true
    openSwing(this._swing)
  }

  /**
   * One frame of the active window: sweep the blade, damage what it reached, and bounce off a wall it
   * reached first. Returns true when the swing ended in a recoil (the state has changed).
   */
  private _stepSwing(): boolean {
    const weapon = this.currentWeapon() as any
    // Not in this character's own hand (no hand socket on its model): the blade is elsewhere, hit nothing.
    if (!wieldedBy(weapon, this)) return false
    const blade = bladeCapsule(weapon)
    if (!blade) return false
    const move = this._move as any
    const contact = stepSwing(this.scene?.physics, this._swing, blade, this, 'enemy', move?.bounceOff !== false)
    // The weapon turns the swing into damage; each target takes it through its own receiveHit.
    for (const t of contact.targets) weapon?.strike?.(this, move, t.node, t.point)
    if (contact.blockedAt && !contact.targets.length) {
      this._recoil(contact.blockedAt)
      return true
    }
    if (contact.blockedAt) closeSwing(this._swing)
    return false
  }

  /** The blade met a wall: sparks, a jolt, and a short stagger with the swing cancelled. */
  private _recoil(at: number[]): void {
    closeSwing(this._swing)
    const gm = this._gm as any
    gm?.fx?.((this.currentWeapon() as any)?.hitSparkTemplate || 'Hit Spark', at)
    gm?.sfx?.('Recoil')
    gm?.shake?.(0.2)
    this._stopAction()
    this._motionDir = this._forward(-1)
    this._enter('recoil')
    this._actionSeconds = this.recoilSeconds
    this._play(this.recoilClip, 1.4)
  }

  private _doDrink(): void {
    this._drank = true
    if (this.estus <= 0) return
    this.estus--
    this._healLeft = this.estusHeal
    this._healRate = this.estusHeal / Math.max(0.05, this.estusHealSeconds)
    ;(this._gm as any)?.sfx?.('Drink')
  }

  // ----- per-frame helpers -------------------------------------------------------------------------

  private _readInput(): void {
    if (Input.started('LightAttack')) this._buffer('light')
    if (Input.started('HeavyAttack')) this._buffer('heavy')
    if (Input.started('UseItem')) this._buffer('item')
    if (Input.started('SwapWeapon')) this._buffer('swap')
    if (Input.started('Interact') && this._interactTarget) this._buffer('interact')

    // Roll is a TAP; holding it is sprint. So the roll fires on RELEASE, and only if this press never
    // turned into a sprint. `heldSeconds` reads 0 on the release frame, hence the copy kept while held.
    if (Input.started('Roll')) { this._rollHeld = 0; this._sprintedThisHold = false }
    if (this._rollHeld >= 0 && Input.pressed('Roll')) this._rollHeld = Input.heldSeconds('Roll')
    if (this.isSprinting) this._sprintedThisHold = true
    if (Input.released('Roll') && this._rollHeld >= 0) {
      if (!this._sprintedThisHold) this._buffer('roll')
      this._rollHeld = -1
    }
  }

  private _buffer(action: string): void {
    this._bufferAction = action
    this._bufferAge = 0
  }

  private _consumeBuffer(): void {
    this._bufferAction = ''
    this._bufferAge = 99
  }

  private _tickStamina(delta: number): void {
    const resting = this.actionState === 'free' || this.actionState === 'rest' || this.actionState === 'gesture'
      || this.actionState === 'swap' || this.actionState === 'drink'
    if (resting && !this.isSprinting && this._sinceSpend >= this.staminaRegenDelay)
      this.stamina = Math.min(this.maxStamina, this.stamina + this.staminaRegen * delta)
  }

  private _tickHeal(delta: number): void {
    if (this._healLeft <= 0) return
    const step = Math.min(this._healLeft, this._healRate * delta)
    this._healLeft -= step
    this.hp = Math.min(this.maxHp, this.hp + step)
  }

  private _spend(amount: number): void {
    this.stamina = Math.max(0, this.stamina - amount)
    this._sinceSpend = 0
  }

  private _computeInvulnerable(): boolean {
    const t = this._stateTime
    switch (this.actionState) {
      case 'roll': return t >= this.rollInvulnStart && t <= this.rollInvulnEnd
      case 'backstep': return t <= this.backstepInvulnEnd
      case 'fog': case 'rest': case 'dead': return true
      default: return false
    }
  }

  /**
   * Entering an interactable's trigger zone makes it a candidate; leaving takes it off. The zones are
   * authored as each interactable's `trigger` volume — no distance is measured in script.
   */
  onTriggerEnter(other: Node) {
    if (other && (other as any).interact && !this._nearby.includes(other)) this._nearby.push(other)
    ;(this._gm as any)?.onPlayerEnteredZone?.(other)
  }

  onTriggerExit(other: Node) {
    this._nearby = this._nearby.filter(n => n !== other)
    ;(this._gm as any)?.onPlayerLeftZone?.(other)
  }

  /** The interactables in range right now, nearest first (for tests and the HUD). */
  public nearbyInteractables(): Node[] { return this._nearby.slice() }

  private _findInteractable(): void {
    this._interactTarget = null
    this.interactPrompt = ''
    if (this.actionState !== 'free' || !this._nearby.length) return
    const me = this.worldPosition
    let best: Node = null
    let bestDistance = Infinity
    for (const node of this._nearby) {
      const n = node as any
      if (!node || node.spawned === false || !n.interact) continue
      if (n.canInteract && !n.canInteract(this)) continue
      // Inside several zones at once (a lever beside a door): the nearest wins.
      const p = node.worldPosition
      const d = Math.hypot(p[0] - me[0], p[2] - me[2])
      if (d < bestDistance) { best = node; bestDistance = d }
    }
    if (!best) return
    this._interactTarget = best
    const b = best as any
    this.interactPrompt = (b.promptText ? b.promptText(this) : b.prompt) || 'Interact'
  }

  private _trackSafeGround(delta: number): void {
    this._safeTimer += delta
    if (this._safeTimer < 0.5) return
    this._safeTimer = 0
    if (this.isGrounded && this.actionState === 'free') {
      const p = this.worldPosition
      this.lastSafePosition = [p[0], p[1], p[2]]
    }
  }

  /** Replace the controller's move with a world direction at a fixed speed (0 stands still). */
  private _driveMotion(intent: any, dir: number[], speed: number): void {
    this.acceleration = 0
    this.facingMode = 'none'
    intent.speedScale = 1
    if (speed <= 0) {
      intent.move[0] = 0
      intent.move[1] = 0
      intent.sprint = false
      return
    }
    setMoveWorld(intent, dir[0], dir[2])
    intent.sprint = true
    this.runSpeed = speed
  }

  private _holdStill(intent: any): void {
    this._driveMotion(intent, this._motionDir, 0)
  }

  private _turnToward(point: ArrayLike<number>, maxDegrees: number): void {
    const me = this.worldPosition
    const dx = point[0] - me[0]
    const dz = point[2] - me[2]
    if (Math.hypot(dx, dz) < 0.05) return
    const want = Math.atan2(dx, dz) * 180 / Math.PI
    const f = this.worldForward
    const have = Math.atan2(f[0], f[2]) * 180 / Math.PI
    let diff = (want - have) % 360
    if (diff > 180) diff -= 360
    else if (diff < -180) diff += 360
    const step = Math.max(-maxDegrees, Math.min(maxDegrees, diff))
    this.setRotation([0, have + step, 0])
  }

  private _forward(sign: number): number[] {
    const f = this.worldForward
    const len = Math.hypot(f[0], f[2]) || 1
    return [sign * f[0] / len, 0, sign * f[2] / len]
  }

  private _dirFrom(from: ArrayLike<number>): number[] {
    const me = this.worldPosition
    const dx = me[0] - from[0]
    const dz = me[2] - from[2]
    const len = Math.hypot(dx, dz)
    return len > 1e-4 ? [dx / len, 0, dz / len] : this._forward(-1)
  }

  private _enter(state: string): void {
    if (state !== 'attack') closeSwing(this._swing)
    this.actionState = state
    this._stateTime = 0
    if (state === 'free') {
      this._move = null
      this._clip = ''
    }
  }

  private _play(clip: string, speed: number, loop: boolean = false): void {
    this._clip = clip
    this._clipLength = this._clipDuration(clip)
    const animator = this._model?.animator as any
    if (!animator?.playAction || !clip) return
    animator.playAction(clip, { speed, loop, blendIn: 0.08, blendOut: 0.18 })
  }

  private _stopAction(): void {
    const animator = this._model?.animator as any
    animator?.stopAction?.(undefined, 0.12)
    this._clip = ''
  }

  private _clipDuration(name: string): number {
    const clip = this._findClip(name)
    if (!clip) return 0
    let end = 0
    for (const s of clip.samplers ?? []) {
      const input = s.input
      if (input && input.length) end = Math.max(end, input[input.length - 1])
    }
    return end
  }

  private _clipHasEvent(name: string, event: string): boolean {
    const clip = this._findClip(name)
    return !!clip?.events?.some((e: any) => e.name === event)
  }

  private _findClip(name: string): any {
    const animations = (this._model?.model as any)?.animations
    if (!animations || !name) return null
    return animations.find((a: any) => a.name === name) ?? null
  }

  private _findModel(): ModelNode {
    const walk = (node: Node): ModelNode => {
      for (const child of node.children) {
        if (child.nodeType === 'model' && (child as any).animator) return child as ModelNode
        if (child.nodeType === 'cameraRig' || child.nodeType === 'controller') continue
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }

}

import { CameraRigNode, Input, Node } from 'cleo'
import { angleDiff, planarDistance, yawTo } from './SoulsMath'

/**
 * Hollow Keep — the third-person camera with target lock. Attach to the Player's `camera rig`, a Camera
 * Rig node that sits BEFORE the Player Controller among the Player's children.
 *
 * Free: an ordinary orbit camera the controller steers with Look.
 *
 * Locked: the rig switches to `aimMode = 'lookAt'` on the target's `LockPoint`, so the camera holds the
 * enemy in frame by itself. The controller keeps writing the rig's yaw into the intent as the aim, which
 * is what makes the player STRAFE around the target — SoulsPlayer sets `facingMode = 'aim'` while locked.
 *
 *   LockOn                   toggle. With nothing to lock, it re-centres the camera behind the player.
 *   SwitchTargetLeft/Right   cycle (keys); a hard flick of the right stick or the mouse does the same
 *
 * Candidates are the manager's live enemies within `lockRange` and in line of sight, ranked by angle off
 * the camera's forward and then by distance (rankLockTargets, below). The lock breaks past
 * `breakRange`, after `losBreakSeconds` behind a wall, or when the target dies — in which case another
 * enemy within `retargetRange` is picked up, as the games do.
 *
 * The reticle is a world-space UI Root named `LockReticle`, a child of the player beside this rig. Its
 * `uiTargetId` is kept pointed at the
 * target's lock point.
 */
export default class SoulsLockOnNode extends CameraRigNode {
  public lockRange: number = 20
  public breakRange: number = 26
  /** Seconds the target may stay hidden behind geometry before the lock lets go. */
  public losBreakSeconds: number = 1.5
  /** Seconds between two target switches, so one flick switches once. */
  public switchCooldown: number = 0.35
  /** Right-stick deflection (scaled ×4 in the map) that counts as a flick. */
  public stickFlick: number = 2.6
  /**
   * Mouse speed, in pixels per SECOND, that counts as a flick. A per-frame pixel threshold made switching
   * targets harder the higher the frame rate, since the same flick is spread over more frames.
   */
  public mouseFlickPerSecond: number = 2700
  /** Pitch limits while locked (positive looks down). Keeps a tall boss from flipping the camera. */
  public lockedPitchMin: number = -25
  public lockedPitchMax: number = 35
  public reticleName: string = 'LockReticle'
  /** When the target dies, the lock jumps to another enemy only if one is this close. */
  public retargetRange: number = 10

  /** The locked enemy (a SoulsEnemy root), or null. SoulsPlayer reads this. */
  public lockTarget: Node = null

  private _gm: Node = null
  private _player: Node = null
  private _reticle: Node = null
  private _hiddenFor: number = 0
  private _switchWait: number = 0
  private _freePitchMin: number = -80
  private _freePitchMax: number = 80

  onStart() {
    this._gm = this.findNode('GameManager')
    this._player = this.parent
    // The reticle is the player's (a sibling of this rig, inside the Player template).
    this._reticle = this._player?.getChildByName(this.reticleName)[0] ?? null
    this._freePitchMin = this.pitchMin
    this._freePitchMax = this.pitchMax
    this.aimMode = 'orbit'
    this._showReticle(null)
  }

  onUpdate(delta: number) {
    this._switchWait = Math.max(0, this._switchWait - delta)
    const player = this._player as any
    if (player?.isDead) { if (this.lockTarget) this.unlock(); return }

    if (Input.started('LockOn')) {
      if (this.lockTarget) this.unlock()
      else if (!this._lockBest()) this._recenter()
    }
    if (!this.lockTarget) return

    // Lost?
    const target = this.lockTarget as any
    if (!target || target.isDead || target.spawned === false || !this.scene?.getNodeById(this.lockTarget.id)) {
      this.onTargetDied(this.lockTarget)
      return
    }
    const me = this._player.worldPosition
    const at = this.lockTarget.worldPosition
    if (Math.hypot(at[0] - me[0], at[2] - me[2]) > this.breakRange) { this.unlock(); return }
    this._hiddenFor = this._hasLineOfSight(this.lockTarget) ? 0 : this._hiddenFor + delta
    if (this._hiddenFor > this.losBreakSeconds) { this.unlock(); return }

    // Switching.
    let dir = 0
    if (Input.started('SwitchTargetLeft')) dir = 1
    if (Input.started('SwitchTargetRight')) dir = -1
    if (!dir && this._switchWait <= 0) {
      const look = Input.vector('Look')
      const device = Input.device('Look')
      // A stick is a deflection; a mouse delta is distance this frame, so it is turned into a speed.
      const amount = device === 'gamepadAxis' ? Math.abs(look[0]) : Math.abs(look[0]) / Math.max(delta, 1e-3)
      const flick = device === 'gamepadAxis' ? this.stickFlick : this.mouseFlickPerSecond
      // Look X is positive to the RIGHT; right means a clockwise (negative) yaw step.
      if (amount >= flick) dir = look[0] > 0 ? -1 : 1
    }
    if (dir) this._switch(dir)
  }

  /** Drop the lock and hand the camera back to the player. */
  public unlock(): void {
    this.lockTarget = null
    this.aimMode = 'orbit'
    this.lookAtId = null
    this.pitchMin = this._freePitchMin
    this.pitchMax = this._freePitchMax
    this._hiddenFor = 0
    this._showReticle(null)
  }

  /** The manager calls this when any enemy dies; only our target matters. */
  public onTargetDied(enemy: Node): void {
    if (!this.lockTarget || enemy !== this.lockTarget) return
    this.unlock()
    const near = this._candidates().find(c => {
      const me = this._player.worldPosition
      return Math.hypot(c.position[0] - me[0], c.position[2] - me[2]) <= this.retargetRange
    })
    if (near) this.lockOnto(near.node)
  }

  /** Lock onto a specific enemy (e.g. the boss when its fight starts). */
  public lockOnto(enemy: Node): void {
    if (!enemy) return
    const point = this._lockPoint(enemy)
    this.lockTarget = enemy
    this.aimMode = 'lookAt'
    this.lookAtId = point.id
    this.lookAtOffset = [0, 0, 0]
    this.pitchMin = this.lockedPitchMin
    this.pitchMax = this.lockedPitchMax
    this._hiddenFor = 0
    this._showReticle(point)
  }

  private _lockBest(): boolean {
    const best = this._candidates()[0]
    if (!best) return false
    this.lockOnto(best.node)
    ;(this._gm as any)?.sfx?.('Lock On')
    return true
  }

  /** Step to the next candidate clockwise (dir -1) or counter-clockwise (dir +1) of the current one. */
  private _switch(dir: number): void {
    this._switchWait = this.switchCooldown
    const current = this.lockTarget
    const me = this._player.worldPosition
    const base = yawTo(me, current.worldPosition)
    let best: Node = null
    let bestStep = Infinity
    for (const c of this._candidates()) {
      if (c.node === current) continue
      // How far round in the requested direction this candidate is, 0..360.
      let step = (yawTo(me, c.position) - base) * dir
      step = ((step % 360) + 360) % 360
      if (step > 0 && step < bestStep) { bestStep = step; best = c.node }
    }
    if (best) this.lockOnto(best)
  }

  private _candidates(): { node: Node, position: ArrayLike<number> }[] {
    const gm = this._gm as any
    if (!gm?.liveEnemies || !this._player) return []
    const list = gm.liveEnemies()
      .filter((e: Node) => this._hasLineOfSight(e))
      .map((e: Node) => ({ node: e, position: e.worldPosition }))
    return this.rankLockTargets(this._player.worldPosition, this.yaw, list, this.lockRange)
  }

  /**
   * Order lock-on candidates: smallest angle off the camera's forward first, distance breaking ties in
   * 10-degree buckets so two enemies side by side resolve to the nearer.
   */
  public rankLockTargets(origin: ArrayLike<number>, yawDeg: number, candidates: any[], maxRange: number): any[] {
    return candidates
      .map(c => ({ c, d: planarDistance(origin, c.position), a: Math.abs(angleDiff(yawTo(origin, c.position), yawDeg)) }))
      .filter(x => x.d <= maxRange)
      .sort((x, y) => (Math.floor(x.a / 10) - Math.floor(y.a / 10)) || (x.d - y.d))
      .map(x => x.c)
  }

  /** Line of sight from the camera pivot to the enemy's lock point, ignoring characters. */
  private _hasLineOfSight(enemy: Node): boolean {
    const physics = this.scene?.physics as any
    if (!physics?.raycast) return true
    const from = this.worldPosition
    const to = this._lockPoint(enemy).worldPosition
    const hit = physics.raycast([from[0], from[1], from[2]], [to[0], to[1], to[2]], {
      reject: (owner: Node) => !!owner && (owner.nodeType === 'character'
        || !!owner.getVariable?.('isEnemy') || !!owner.getVariable?.('isPlayer')),
    })
    return !hit
  }

  private _lockPoint(enemy: Node): Node {
    const e = enemy as any
    return (e.lockPoint ? e.lockPoint() : null) ?? enemy.getChildByName('LockPoint')[0] ?? enemy
  }

  /** Swing the camera behind the player — what pressing lock with nothing in range does. */
  private _recenter(): void {
    if (!this._player) return
    const f = this._player.worldForward
    this.setOrbit(Math.atan2(f[0], f[2]) * 180 / Math.PI, 12)
  }

  private _showReticle(point: Node): void {
    const reticle = this._reticle as any
    if (!reticle) return
    reticle.uiTargetId = point ? point.id : null
    if (reticle.visible !== !!point) reticle.visible = !!point
  }
}

import { CharacterNode, Logger, Node, Shape, resolveSocketOwner } from 'cleo'
import { clamp } from './SoulsMath'
import { bladeCapsule } from './SoulsHitbox'

/**
 * Hollow Keep — what every fighter is: the player, and each enemy type. A base script; the player
 * (SoulsPlayer) and the enemies (SoulsEnemy, then SoulsHollow, SoulsEliteKnight…) extend it, so each
 * owns its own health, defence and weapons as fields on its own node — no manager keeps them.
 *
 * ## Taking a hit
 *
 * `receiveHit(damage, poise, from)` is the ONE way damage arrives, from a blade (SoulsWeapon.strike), a
 * slam or a bolt alike. It runs the same steps for everyone and leaves the reaction to the subclass:
 *
 *   _canBeHit(damage)     false = it passes through (dead, rolling, roaring…)
 *   applyDefense          this character's own `defense` takes its share
 *   hp -= dealt, bleed
 *   _onHurt(dealt, from)  always — wake up, turn the health bar on, play a hurt sound
 *   hp <= 0 ? _die()      : _onDamaged(dealt, poise, from) — flinch, stagger, phase two
 *
 * `team` is what an attack reads to pick its targets: a player's blade hits `enemy` hurtboxes, an
 * enemy's hits `player` ones, so two enemies never cut each other down by accident.
 *
 * ## Weapons
 *
 * A character names its weapons by TEMPLATE in `weaponTemplates` ("Straight Sword, Greatsword") and
 * spawns them on start under its `Weapons` group (or itself), attached to `weaponSocket`. The first is
 * equipped; `equipWeapon(i)` shows one and hides the rest. The weapon brings its own stats, hitbox and
 * moveset — see SoulsWeapon.
 *
 * `dropWeapon()` lets go of the held one: it leaves the hand for the world and becomes a physics body
 * (spheres along its blade), so it falls, rolls and can be kicked about. It still belongs to this
 * character, and goes when the character does (`_clearDroppedWeapons`, from the subclass's onDespawn).
 */
export default class SoulsCharacterNode extends CharacterNode {
  public displayName: string = 'Character'
  /** Which side attacks see this on: 'player' or 'enemy'. */
  public team: string = 'enemy'
  public maxHp: number = 100
  public hp: number = 100
  /** Fraction of incoming damage ignored, 0..0.9. */
  public defense: number = 0
  /** Collision-ish size, used by hit effects and lock-on height. */
  public bodyRadius: number = 0.4
  public bodyHeight: number = 1.8

  /** Weapon templates to spawn on start, comma separated. The first is held. */
  public weaponTemplates: string = ''
  /** Socket on this character's skeleton the weapons attach to. */
  public weaponSocket: string = 'RightHand'
  /** Child group the weapons are spawned under (this node itself when there is none). */
  public weaponsGroup: string = 'Weapons'
  /** The held weapon's display name, for the HUD. */
  public weaponName: string = ''
  /** Let go of the held weapon on death, as a physics body (see dropWeapon). */
  public dropWeaponOnDeath: boolean = false
  /** The dropped weapon's mass, kg. */
  public droppedWeaponMass: number = 4

  // ----- runtime, read by others -------------------------------------------------------------------
  public isDead: boolean = false
  /**
   * Whether attacks can see this character at all. Off during i-frames, while dead, during a boss's
   * roar: every hitbox sweep and bolt passes straight through. See SoulsHitbox.
   */
  public hurtboxActive: boolean = true

  protected _gm: Node = null
  protected _weapons: Node[] = []
  protected _weaponIndex: number = 0
  protected _dropped: Node[] = []

  // =================================================================================================
  // Damage
  // =================================================================================================

  /** Damage that survives this character's defence (0..0.9). Never below 1, so a hit always registers. */
  public applyDefense(raw: number): number {
    return Math.max(1, Math.round(raw * (1 - clamp(this.defense, 0, 0.9))))
  }

  /** Take a hit. Returns true when it landed. See "Taking a hit". */
  public receiveHit(damage: number, poiseDamage: number, from: Node): boolean {
    if (!this._canBeHit(damage)) return false
    const dealt = this.applyDefense(damage)
    this.hp = Math.max(0, this.hp - dealt)
    ;(this._gm as any)?.bleed?.(this, from, dealt)
    this._onHurt(dealt, from)
    if (this.hp <= 0) this._die()
    else this._onDamaged(dealt, poiseDamage, from)
    return true
  }

  /** Whether a hit of `damage` lands right now. */
  protected _canBeHit(damage: number): boolean {
    return !this.isDead && damage > 0
  }

  /** Every landed hit, before the death check. */
  protected _onHurt(dealt: number, from: Node): void {}

  /** A landed hit that did not kill. */
  protected _onDamaged(dealt: number, poiseDamage: number, from: Node): void {}

  protected _die(): void {
    this.isDead = true
  }

  // =================================================================================================
  // Weapons
  // =================================================================================================

  /** Spawn every weapon in `weaponTemplates` into the hand, and hold the first. */
  protected _spawnWeapons(): void {
    for (const w of this._weapons) { try { w.remove() } catch { /* already gone */ } }
    this._weapons = []
    const names = (this.weaponTemplates || '').split(',').map(s => s.trim()).filter(Boolean)
    const parent = this.getChildByName(this.weaponsGroup)[0] ?? this
    for (const name of names) {
      const weapon = this.scene?.instantiate(name, { parent })
      if (!weapon) continue   // instantiate has logged the missing template
      if (!(weapon as any).isWeapon) {
        Logger.warn('Hollow Keep: "' + name + '" is not a weapon template (its root has no SoulsWeapon script).', 'Script')
        weapon.remove()
        continue
      }
      weapon.attachToSocket('parent', this.weaponSocket)
      this._weapons.push(weapon)
    }
    // Said once, here, rather than discovered as "attacks do no damage": the weapon can only be held by a
    // hand this character's own model has. Humanoid rigs get RightHand/LeftHand without authoring.
    const first = this._weapons[0]
    if (first && !resolveSocketOwner(first, { target: 'parent', socket: this.weaponSocket }, id => this.scene?.getNodeById(id) ?? null))
      Logger.warn('Hollow Keep: "' + this.name + '"\'s model has no "' + this.weaponSocket + '" socket, so it cannot hold its weapon. '
        + 'Add a socket with that name on its hand bone in the rig editor (or set weaponSocket to one it has).', 'Script')
    if (names.length && !this._weapons.length)
      Logger.warn('Hollow Keep: "' + this.name + '" has no usable weapon among "' + this.weaponTemplates + '".', 'Script')
    this.equipWeapon(0)
  }

  /** Every weapon this character carries, in `weaponTemplates` order. */
  public weapons(): Node[] { return this._weapons }

  /** The weapon in hand (a SoulsWeapon node), or null. */
  public currentWeapon(): Node { return this._weapons[this._weaponIndex] ?? null }

  /**
   * Let go of the held weapon. It is moved to the scene root where it is (a body must not be parented,
   * see the scripting docs), detached from the hand, and given a dynamic body made of spheres along its
   * blade hitbox. Not solid to the camera. Returns the weapon, or null with none held.
   */
  public dropWeapon(): Node {
    const weapon = this.currentWeapon()
    const root = this.scene?.root
    if (!weapon || !root) return null
    const blade = bladeCapsule(weapon)
    const at = Array.from(weapon.worldPosition), q = Array.from(weapon.worldQuaternion)
    weapon.detachFromSocket()
    root.addChild(weapon)
    weapon.setPosition([at[0], at[1], at[2]])
    weapon.setQuaternion(q as any)
    weapon.updateTransforms?.()
    const body: any = weapon.setBody(this.droppedWeaponMass, 0.05, 0.3, undefined, undefined, 0.8, 0.1, true, false)
    const points = blade
      ? [blade.a, [(blade.a[0] + blade.b[0]) / 2, (blade.a[1] + blade.b[1]) / 2, (blade.a[2] + blade.b[2]) / 2], blade.b]
      : [at]
    const radius = Math.max(0.04, blade?.radius ?? 0.08)
    for (const p of points) body.attachShape(Shape.Sphere(radius), toLocal(q, at, p))
    body.recenterMass?.()
    this._weapons = this._weapons.filter(w => w !== weapon)
    this._dropped.push(weapon)
    this.weaponName = ''
    return weapon
  }

  /** Every weapon this character has dropped, still lying about. */
  public droppedWeapons(): Node[] { return this._dropped }

  /** Remove the weapons this character dropped. Called when the character itself goes. */
  protected _clearDroppedWeapons(): void {
    for (const w of this._dropped) { try { w.remove() } catch { /* already gone */ } }
    this._dropped = []
  }

  /** Hold weapon `index`: it shows, the others hide. */
  public equipWeapon(index: number): void {
    this._weaponIndex = Math.max(0, Math.min(index, this._weapons.length - 1))
    this._weapons.forEach((w, i) => { if (w.visible !== (i === this._weaponIndex)) w.visible = i === this._weaponIndex })
    this.weaponName = (this.currentWeapon() as any)?.displayName ?? ''
  }
}

/** `p` (world) in the frame of a node at `at` with rotation `q` — the inverse rotation of p − at. */
function toLocal(q: ArrayLike<number>, at: ArrayLike<number>, p: ArrayLike<number>): [number, number, number] {
  const v = [p[0] - at[0], p[1] - at[1], p[2] - at[2]]
  // Rotate by the conjugate (-x, -y, -z, w): v' = v + 2w(c×v) + 2c×(c×v), with c = -q.xyz.
  const cx = -q[0], cy = -q[1], cz = -q[2], w = q[3]
  const tx = 2 * (cy * v[2] - cz * v[1]), ty = 2 * (cz * v[0] - cx * v[2]), tz = 2 * (cx * v[1] - cy * v[0])
  return [v[0] + w * tx + (cy * tz - cz * ty), v[1] + w * ty + (cz * tx - cx * tz), v[2] + w * tz + (cx * ty - cy * tx)]
}

import { Node } from 'cleo'
import { num, statBonus } from './SoulsMath'

/**
 * Hollow Keep — the base WEAPON. Every weapon is its own template, made from the base "Weapon" template
 * as a VARIANT, with its own script extending this one:
 *
 *   Weapon (template)            this script; Socket: RightHand (attach to socket, target parent)
 *   └── Mesh                     the visible weapon — its local transform IS the grip
 *
 *   Straight Sword (variant)     SoulsStraightSword extends SoulsWeapon — its stats are that class's defaults
 *   ├── Mesh                     inherited, given the sword's parts and grip
 *   ├── Light1 Light2 Light3     SoulsMove data nodes, added by the variant — the moveset and its clips
 *   └── Heavy
 *
 * A character does not carry its weapons in its template. It names them (`weaponTemplates` on
 * SoulsCharacter) and spawns them on start, into the hand. So the same "Greatsword" template is the
 * player's second weapon and the Elite Knight's only one, and a change to it reaches both.
 *
 * The weapon owns everything about itself: its numbers, its hitbox, its moves (with the clips the wielder
 * plays), and the maths that turns a swing into damage (`attackRating`, `hitFor`, `strike`). The wielder
 * only decides WHEN to swing and WHAT the blade reached.
 *
 * The weapon node itself is driven by the socket every frame, so never offset IT to fix a grip: rotate
 * and move the `Mesh` child instead (see SOULS_DEMO.md, "Swapping a weapon").
 *
 * ## Hitbox
 *
 * `bladeStart`/`bladeEnd`/`bladeRadius` is a capsule along the blade, in the `Mesh` child's space. During
 * an attack's active window it is swept every frame against hurtboxes (SoulsHitbox).
 *
 * ## Attack rating
 *
 *   AR = baseDamage × (1 + strScaling·bonus(STR) + dexScaling·bonus(DEX)),  × unmetRequirementPenalty
 *        when a requirement is unmet
 */
export default class SoulsWeaponNode extends Node {
  public displayName: string = 'Weapon'
  public baseDamage: number = 100
  /** How fully the weapon scales with each stat: 1.0 is an "A", 0.2 an "E". */
  public strScaling: number = 0
  public dexScaling: number = 0
  public strRequirement: number = 0
  public dexRequirement: number = 0
  /** Attack-rating multiplier when the wielder misses a STR or DEX requirement. */
  public unmetRequirementPenalty: number = 0.6
  /** Poise damage per hit, before the move's own multiplier. */
  public poiseDamage: number = 15
  /** Multiplies every move's stamina cost. */
  public staminaMul: number = 1
  /** First move of the light chain, and the heavy attack. Names of child SoulsMove nodes. */
  public lightMove: string = 'Light1'
  public heavyMove: string = 'Heavy'
  /** The blade hitbox, in the Mesh child's space. See "Hitbox" above. */
  public bladeStart: number[] = [0, 0.12, 0]
  public bladeEnd: number[] = [0, 1, 0]
  public bladeRadius: number = 0.12
  /** Effect spawned where the blade meets a body, and the sound of the hit. */
  public hitSparkTemplate: string = 'Hit Spark'
  public hitSound: string = 'Hit'
  /** Marker characters look for among the nodes they spawn (a script class is never `instanceof`). */
  public isWeapon: boolean = true

  protected _gm: Node = null

  onStart() {
    this._gm = this.findNode('GameManager')
  }

  /** The child SoulsMove named `name`, or null. */
  public findMove(name: string): Node {
    if (!name) return null
    const found = this.getChildByName(name)[0]
    return found && (found as any).isMove ? found : null
  }

  /** Every move, in hierarchy order. */
  public moves(): Node[] {
    return this.children.filter(c => (c as any).isMove)
  }

  /** This weapon's attack rating in the hands of someone with these stats. See "Attack rating". */
  public attackRating(strength: number, dexterity: number): number {
    let ar = this.baseDamage * (1 + this.strScaling * statBonus(strength) + this.dexScaling * statBonus(dexterity))
    if (strength < this.strRequirement || dexterity < this.dexRequirement) ar *= this.unmetRequirementPenalty
    return Math.round(ar)
  }

  /**
   * What one hit of `move` deals when `wielder` swings this: attack rating (from the wielder's own
   * STR/DEX, 10 when it has none) × the move's damage multiplier, and poise × the move's poise multiplier.
   */
  public hitFor(wielder: Node, move: any): { damage: number; poise: number } {
    const w = wielder as any
    const ar = this.attackRating(num(w?.strength, 10), num(w?.dexterity, 10))
    return {
      damage: Math.round(ar * num(move?.damageMul, 1)),
      poise: this.poiseDamage * num(move?.poiseMul, 1),
    }
  }

  /**
   * The blade reached `target`'s hurtbox at `point` during `move`. The target takes the hit through its
   * own `receiveHit` (its defence, its poise, its reaction are its business). Returns true if it landed.
   */
  public strike(wielder: Node, move: any, target: Node, point: ArrayLike<number>): boolean {
    const t = target as any
    if (!wielder || typeof t?.receiveHit !== 'function') return false
    const { damage, poise } = this.hitFor(wielder, move)
    if (!t.receiveHit(damage, poise, wielder)) return false
    const gm = (this._gm ?? this.findNode?.('GameManager')) as any
    if (point) gm?.fx?.(this.hitSparkTemplate, point)
    gm?.sfx?.(this.hitSound)
    return true
  }
}

import { Logger, ModelNode, Node, setMoveWorld } from 'cleo'
import { clamp, num, planarDistance } from './SoulsMath'
import { Swing, bladeCapsule, closeSwing, newSwing, openSwing, stepSwing, wieldedBy } from './SoulsHitbox'
import SoulsCharacterNode from './SoulsCharacter'

/**
 * Hollow Keep — the base ENEMY. Never attached as-is: each enemy type has its own script extending this
 * one (SoulsHollow, SoulsHollowSorcerer, SoulsEliteKnight, SoulsHollowWarden), whose defaults are that
 * type's stats, and its own template, a variant of the base "Enemy" template. This class is everything
 * the types share: how an enemy fights, spaces, reacts and dies.
 *
 *   Hollow                Character (SoulsHollow) — capsule body, friction 0
 *   ├── <model>           skinned model with a state machine that has `Died` and `Revive` triggers
 *   ├── LockPoint *       empty node at chest height: where the lock-on camera and reticle aim
 *   ├── Weapons           empty group; `weaponTemplates` (e.g. "Club") is spawned into it on start, into
 *   │                     the RightHand socket. The weapon's blade is the melee HITBOX (see SoulsHitbox)
 *   ├── Attacks *         group of SoulsEnemyAttack data nodes — the moveset
 *   ├── HealthBar         world-space UI Root with a `Fill` progress bar (optional; not on the boss)
 *   ├── PhaseAura         particle system started when the boss turns (optional)
 *   └── Brain             ControllerNode, source AI, SoulsEnemyBrain — LAST child
 *
 * ## Who drives
 *
 * The Brain's behaviour machine handles everything that is navigation: Idle at home, Chase along the
 * navmesh, Return home when leashed. Once it reaches its `Engage` state it hands the body over (goal
 * `script`) and THIS script fights: spacing, strafing, choosing attacks, reacting to hits. Attacks,
 * flinches and death override movement in any brain state.
 *
 * ## Poise
 *
 * Each hit subtracts its poise damage. At zero the enemy STAGGERS — the attack it was in is cancelled —
 * and poise refills. It also refills after `poiseRegenDelay` seconds without being hit. Regular enemies
 * additionally FLINCH on every hit unless the attack they are in has `hyperArmor`; a boss never flinches,
 * only staggers.
 *
 * ## Bosses
 *
 * `isBoss` enemies start DORMANT and stand still until the fog gate calls `awaken()`, never flinch, and
 * have no floating health bar (the HUD reads the boss itself). What a boss does at low health is its own
 * script's business — see SoulsHollowWarden, which overrides `_onDamaged` for its phase two.
 */
export default class SoulsEnemyNode extends SoulsCharacterNode {
  public displayName: string = 'Enemy'
  public team: string = 'enemy'
  public maxPoise: number = 25
  public poiseRegenDelay: number = 3
  public soulsReward: number = 120
  public isBoss: boolean = false
  /** A dead enemy lets its weapon fall (a physics body); it lies there until the corpse goes. */
  public dropWeaponOnDeath: boolean = true

  // ----- movement --------------------------------------------------------------------------------
  // WHEN to chase, close in, strafe, back off or give up is the type's AI graph (its `.brain`, linked on
  // the Brain controller): the engage distance, the spacing band and the leash are numbers in ITS
  // transitions. This script only carries out the state the graph is in — see `_ai`.
  /** Chase / approach speed. Patrol and return run slower through the brain's speed scales. */
  public moveSpeed: number = 3
  /** Degrees per second the body turns toward the player while engaged. */
  public engageTurnRate: number = 300
  public strafeSpeedScale: number = 0.35
  public retreatSpeedScale: number = 0.7

  // ----- fighting --------------------------------------------------------------------------------
  /** Seconds of breathing room between attacks (a random value in this range). */
  public attackGapMin: number = 0.6
  public attackGapMax: number = 1.2
  public flinchOnHit: boolean = true
  public flinchClip: string = 'Souls_HitLight'
  public flinchSeconds: number = 0.4
  public staggerClip: string = 'Souls_HitHeavy'
  public staggerSeconds: number = 1.2
  /** Seconds the death clip plays before the ragdoll takes over (0 = no ragdoll). */
  public deathSeconds: number = 1.6
  public useRagdoll: boolean = true
  /** Seconds the body lies there before it is removed. */
  public corpseSeconds: number = 6
  /** Socket projectiles leave from. */
  public castSocket: string = 'LeftHand'
  /** Seconds the health bar stays up after the last hit. */
  public healthBarSeconds: number = 4

  // ----- runtime, read by others -------------------------------------------------------------------
  public isAwake: boolean = true
  /** Which attacks are unlocked: an attack's `phase` is the phase it needs (see pickAttack). */
  public phase: number = 1
  public poise: number = 25
  public fightState: string = 'ai'
  /** Where the enemy was spawned; the brain walks back here. */
  public home: number[] = [0, 0, 0]
  /**
   * Published for the AI graph's Attack Ready: the breathing gap since the last attack has passed AND the
   * moveset has something for the current distance. The graph decides to attack; this script picks which.
   */
  public attackReady: boolean = false

  // ----- what the AI graph reads (builtin parameters) -----------------------------------------------
  /** The brain's current target has died — the graph walks home. */
  public get targetDead(): boolean {
    const id = (this._brain as any)?.getBlackboard?.('target')
    const target: any = typeof id === 'string' && id ? this.scene?.getNodeById(id) : null
    return !!target?.isDead
  }
  /** Planar metres from where the enemy spawned — the graph's leash and "home again" tests. */
  public get distanceFromHome(): number {
    const p = this.worldPosition
    return Math.hypot(p[0] - this.home[0], p[2] - this.home[2])
  }
  public get isAttacking(): boolean { return this.fightState === 'attack' }
  /** A flinch or a stagger is playing out. */
  public get isReacting(): boolean { return this.fightState === 'flinch' || this.fightState === 'stagger' }
  /** A boss's invulnerable phase transition is playing out. */
  public get isPhaseShifting(): boolean { return this.fightState === 'phase' }

  protected _player: Node = null
  protected _model: ModelNode = null
  protected _brain: Node = null
  protected _lockPoint: Node = null
  protected _healthBar: Node = null
  protected _healthFill: Node = null
  protected _aura: Node = null
  private _attacks: Node[] = []
  private _offEvents: (() => void) | null = null

  private _stateTime: number = 0
  private _sinceHit: number = 99
  private _gap: number = 1
  private _cooldowns: any = {}
  private _lastAttack: string = ''
  private _attack: any = null
  private _clip: string = ''
  private _clipLength: number = 0
  private _playSpeed: number = 1
  private _usesEvents: boolean = false
  /** The attack's active window has opened (its `hit` event, or the fallback `hitTime`). */
  private _windowOpened: boolean = false
  private _swing: Swing = newSwing()
  private _actionSeconds: number = 0
  private _lungeSpeedNow: number = 0
  private _strafeDir: number = 1
  private _strafeTimer: number = 0
  /** Multiplies movement and attack speed (a boss's later phase raises it). */
  protected _speedMul: number = 1
  private _reactSeconds: number = 0
  /** How long the current `phase` state (an invulnerable transition) lasts. */
  protected _phaseSeconds: number = 0

  onStart() {
    this.setVariable('isEnemy', true, 'boolean', 'public')
    this._gm = this.findNode('GameManager')
    this._player = this.findNode('Player')
    this._model = this._findModel()
    this._brain = this.children.find(c => c.nodeType === 'controller') ?? null
    this._lockPoint = this.getChildByName('LockPoint')[0] ?? null
    this._healthBar = this.getChildByName('HealthBar')[0] ?? null
    this._healthFill = this._healthBar ? this._find(this._healthBar, 'Fill') : null
    this._aura = this.getChildByName('PhaseAura')[0] ?? null
    this._spawnWeapons()
    const group = this.getChildByName('Attacks')[0]
    this._attacks = group ? group.children.filter(c => (c as any).isEnemyAttack) : []
    if (!this._attacks.length) Logger.warn('Hollow Keep: enemy "' + this.name + '" has no Attacks.', 'Script')

    const p = this.worldPosition
    this.home = [p[0], p[1], p[2]]
    this.hp = this.maxHp
    this.poise = this.maxPoise
    this.isDead = false
    this.phase = 1
    this._speedMul = 1
    this.isAwake = !this.isBoss
    this.fightState = this.isBoss ? 'dormant' : 'ai'
    this._gap = this._rand(this.attackGapMin, this.attackGapMax)
    this._setBar(false)
    ;(this._aura as any)?.stop?.(true)

    const animator = this._model?.animator as any
    // The character's idle/locomotion/death machine is embedded in its model node. A model swapped by
    // deleting the node and dropping a new one in has none, and would walk around in its bind pose with
    // nothing to say why. Linking the mannequin rig gives it the "Souls Character" controller.
    const machine = animator?.getStateMachine?.()
    if (animator && !machine?.states?.length)
      Logger.warn('Hollow Keep: "' + this.name + '" has no animation controller on its model, so it will hold its bind pose. '
        + 'Select the model node and assign "Souls Character" in its Animation section (or link the mannequin rig).', 'Script')
    if (animator?.onAnimationEvent) {
      this._offEvents = animator.onAnimationEvent((name: string, clip: string) => this._onAnimEvent(name, clip))
    }
    ;(this._gm as any)?.registerEnemy?.(this)
  }

  onDespawn() {
    this._offEvents?.()
    this._offEvents = null
    ;(this._gm as any)?.unregisterEnemy?.(this)
    // The weapon it dropped went to the world root, so it does not go with the corpse on its own.
    this._clearDroppedWeapons()
  }

  // =================================================================================================
  // Public API
  // =================================================================================================

  /** The node the lock-on camera aims at. */
  public lockPoint(): Node { return this._lockPoint ?? this }

  /** Wake a dormant boss: it starts hunting the player straight away. */
  public awaken(): void {
    if (this.isDead) return
    this.isAwake = true
    if (this.fightState === 'dormant') this._enter('ai')
    ;(this._brain as any)?.setBlackboard?.('target', this._player?.id)
  }

  // ----- taking hits (SoulsCharacter.receiveHit calls these) -----------------------------------------

  /** Nothing lands on the dead, or during an invulnerable phase transition. */
  protected _canBeHit(damage: number): boolean {
    return super._canBeHit(damage) && this.fightState !== 'phase'
  }

  /** Anything that hurts us is now our target, even from behind. */
  protected _onHurt(dealt: number, from: Node): void {
    this._sinceHit = 0
    if (!this.isBoss) this._setBar(true)
    if (!this.isBoss || this.isAwake) {
      this.isAwake = true
      if (this.fightState === 'dormant') this._enter('ai')
      if (from) (this._brain as any)?.setBlackboard?.('target', from.id)
    }
  }

  /** Poise: at zero, a stagger; otherwise a flinch, unless armoured. */
  protected _onDamaged(dealt: number, poiseDamage: number, from: Node): void {
    this.poise -= poiseDamage
    if (this.poise <= 0) {
      this.poise = this.maxPoise
      this._react('stagger', this.staggerClip, this.staggerSeconds)
      ;(this._gm as any)?.sfx?.('Stagger')
    } else if (this.flinchOnHit && !this.isBoss && !(this.fightState === 'attack' && this._attack?.hyperArmor)) {
      this._react('flinch', this.flinchClip, this.flinchSeconds)
    }
  }

  /**
   * Choose the next attack.
   *
   * Eligible: off cooldown, `minRange <= distance <= maxRange`, and allowed in this `phase` (an attack's
   * `phase` is the phase it UNLOCKS at — 0 and 1 mean always, 2 means only once a boss has turned).
   * The same attack twice in a row is avoided whenever anything else qualifies. Then weighted random.
   *
   * `attacks` are plain records (or SoulsEnemyAttack nodes) and `cooldowns` maps name -> seconds left,
   * so the choice is testable with no scene at all.
   */
  public pickAttack(attacks: any[], distance: number, phase: number, lastName: string,
    cooldowns: any, random: number): any {
    const ok = (a: any) => (num(a.phase, 0) <= Math.max(1, phase))
      && distance >= num(a.minRange, 0) && distance <= num(a.maxRange, 3)
      && !(cooldowns && cooldowns[a.name] > 0)
    let pool = attacks.filter(ok)
    if (pool.length > 1) {
      const fresh = pool.filter(a => a.name !== lastName)
      if (fresh.length) pool = fresh
    }
    if (!pool.length) return null
    const total = pool.reduce((s, a) => s + Math.max(0.0001, num(a.weight, 1)), 0)
    let pick = clamp(random, 0, 0.999999) * total
    for (const a of pool) {
      pick -= Math.max(0.0001, num(a.weight, 1))
      if (pick <= 0) return a
    }
    return pool[pool.length - 1]
  }

  /** Called by the spawn point when re-creating; also usable to reset in place. */
  public resetForRespawn(): void {
    this.hp = this.maxHp
    this.poise = this.maxPoise
    this.isDead = false
    this.phase = 1
    this._speedMul = 1
    this.isAwake = !this.isBoss
    this._enter(this.isBoss ? 'dormant' : 'ai')
  }

  // =================================================================================================
  // The frame
  // =================================================================================================

  onUpdate(delta: number) {
    this._stateTime += delta
    this._sinceHit += delta
    for (const key of Object.keys(this._cooldowns)) this._cooldowns[key] = Math.max(0, this._cooldowns[key] - delta)
    if (this._sinceHit > this.poiseRegenDelay) this.poise = this.maxPoise
    if (this._healthBar && !this.isBoss && this._sinceHit > this.healthBarSeconds) this._setBar(false)
    if (this._healthFill) (this._healthFill as any).value = this.hp / Math.max(1, this.maxHp)

    const intent = this.drive()
    // Re-earned every frame by `_ai`; anything else (an attack, a stagger, death) is not ready.
    this.attackReady = false
    this.walkSpeed = this.moveSpeed * this._speedMul
    this.runSpeed = this.walkSpeed
    intent.sprint = false

    switch (this.fightState) {
      case 'dead':
      case 'dormant':
        this._still(intent)
        return
      case 'attack': this._attacking(intent, delta); return
      case 'flinch':
      case 'stagger':
        this._still(intent)
        if (this._stateTime >= this._reactSeconds) this._enter('ai')
        return
      case 'phase':
        this._still(intent)
        if (this._stateTime >= this._phaseSeconds) this._enter('ai')
        return
      default: this._ai(intent, delta)
    }
  }

  /**
   * Carry out the AI graph's current state. The graph has already decided; this is the doing:
   *
   *   Idle, Chase, Approach, Return   the brain steers (idle / path / seek); the body faces where it walks
   *   Attack                          pick WHICH attack (weighted, cooldowns, range) and start it
   *   Strafe                          circle the player, facing them
   *   Retreat                         back-pedal to the spacing band, facing them
   *   Stagger, Phase Shift, Dead      handled by `fightState` before this runs
   *
   * Every engaged frame it also publishes `attackReady`, which is how the graph knows it MAY attack.
   */
  private _ai(intent: any, delta: number): void {
    const state: string = (this._brain as any)?.behaviorState ?? 'Idle'
    this.acceleration = 12
    this.turnSpeed = this.engageTurnRate
    const engaged = state === 'Approach' || state === 'Strafe' || state === 'Retreat' || state === 'Attack'
    const player = this._player as any
    if (!engaged || !player || player.isDead) {
      this.facingMode = 'velocity'
      return
    }

    const me = this.worldPosition
    const at = this._player.worldPosition
    const dx = at[0] - me[0]
    const dz = at[2] - me[2]
    const dist = Math.hypot(dx, dz)
    const toward = dist > 1e-4 ? [dx / dist, dz / dist] : [0, 1]

    this._gap -= delta
    // `random = 0` makes this a pure "is anything eligible" test — the real draw happens on Attack.
    this.attackReady = this._gap <= 0
      && !!this.pickAttack(this._attacks, dist, this.phase, this._lastAttack, this._cooldowns, 0)

    if (state === 'Approach') { this.facingMode = 'velocity'; return }

    if (state === 'Attack') {
      const attack = this.pickAttack(this._attacks, dist, this.phase, this._lastAttack, this._cooldowns, Math.random())
      this._still(intent)
      if (attack) this._startAttack(attack)
      else this._turnToward(at, this.engageTurnRate * delta)
      return
    }

    // Strafe or Retreat: move relative to the player while facing them.
    this._strafeTimer -= delta
    if (this._strafeTimer <= 0) { this._strafeTimer = this._rand(1.5, 3.5); this._strafeDir = Math.random() < 0.5 ? -1 : 1 }
    let mx = 0, mz = 0, scale = 0
    if (state === 'Retreat') { mx = -toward[0]; mz = -toward[1]; scale = this.retreatSpeedScale }
    else if (this.strafeSpeedScale > 0) {
      // Perpendicular to the line to the player: right of it is (-z, x) rotated by the convention.
      mx = toward[1] * this._strafeDir; mz = -toward[0] * this._strafeDir; scale = this.strafeSpeedScale
    }

    this.facingMode = 'aim'
    if (scale > 0) {
      setMoveWorld(intent, mx, mz)
      intent.speedScale = scale
    } else {
      intent.move[0] = 0
      intent.move[1] = 0
      this._turnToward(at, this.engageTurnRate * delta)
    }
    intent.aimYaw = Math.atan2(dx, dz) * 180 / Math.PI
  }

  // ----- attacks ---------------------------------------------------------------------------------

  private _startAttack(attack: any): void {
    this._attack = attack
    this._lastAttack = attack.name
    this._cooldowns[attack.name] = num(attack.cooldown, 0)
    this._windowOpened = false
    closeSwing(this._swing)
    this._enter('attack')
    this._playSpeed = Math.max(0.05, num(attack.playSpeed, 1) * this._speedMul)
    this._play(attack.clip, this._playSpeed)
    this._usesEvents = this._clipHasEvent(attack.clip, 'hit') || this._clipHasEvent(attack.clip, 'cast')
    const length = this._clipLength > 0 ? this._clipLength : num(attack.hitTime, 0.6) + 0.6
    this._actionSeconds = length / this._playSpeed

    // A leap covers whatever distance there is, within reason.
    this._lungeSpeedNow = num(attack.lungeSpeed, 0)
    if (attack.lungeToTarget && this._player) {
      const d = planarDistance(this.worldPosition, this._player.worldPosition)
      this._lungeSpeedNow = Math.min(num(attack.lungeSpeed, 12), Math.max(0, d - 1) / Math.max(0.05, num(attack.lungeSeconds, 0.5)))
    }
    ;(this._gm as any)?.sfx?.(attack.sound || 'Enemy Swing')
  }

  private _attacking(intent: any, delta: number): void {
    const attack = this._attack
    const t = this._stateTime * this._playSpeed
    if (!this._usesEvents) {
      const hitTime = num(attack?.hitTime, 0.6)
      if (!this._windowOpened && t >= hitTime) this._land()
      if (this._swing.open && t >= hitTime + num(attack?.activeSeconds, 0.15)) closeSwing(this._swing)
    }
    if (this._swing.open) this._stepSwing()

    if (this._player && this._stateTime < num(attack?.trackSeconds, 0.4))
      this._turnToward(this._player.worldPosition, this.engageTurnRate * 1.5 * delta)

    const start = num(attack?.lungeStart, 0)
    const lunging = t >= start && t < start + num(attack?.lungeSeconds, 0) * this._playSpeed
    this.acceleration = 0
    this.facingMode = 'none'
    if (lunging && this._lungeSpeedNow > 0) {
      const f = this.worldForward
      setMoveWorld(intent, f[0], f[2])
      intent.sprint = true
      intent.speedScale = 1
      this.runSpeed = this._lungeSpeedNow
    } else {
      intent.move[0] = 0
      intent.move[1] = 0
    }

    if (this._stateTime >= this._actionSeconds) {
      const next = attack?.comboNext ? this._attacks.find(a => a.name === attack.comboNext) : null
      if (next && this._player && planarDistance(this.worldPosition, this._player.worldPosition) <= num((next as any).maxRange, 3) + 1) {
        this._startAttack(next)
        return
      }
      this._gap = this._rand(this.attackGapMin, this.attackGapMax) / this._speedMul
      this._enter('ai')
    }
  }

  private _onAnimEvent(name: string, clip: string): void {
    if (this.fightState !== 'attack' || (clip && clip !== this._clip)) return
    if ((name === 'hit' || name === 'cast') && !this._windowOpened) this._land()
    else if (name === 'hitEnd') closeSwing(this._swing)
  }

  /**
   * The contact frame. A projectile attack fires; a slam (`aoeRadius`) hits every player hurtbox inside
   * the radius at once; a melee attack opens its active window, and the weapon is swept every frame
   * until `hitEnd` (see _stepSwing).
   */
  private _land(): void {
    this._windowOpened = true
    const attack = this._attack
    if (!attack) return
    const gm = this._gm as any
    if (attack.projectileTemplate) { this._fire(attack); return }
    const aoe = num(attack.aoeRadius, 0)
    if (aoe > 0) {
      gm?.shake?.(0.5)
      gm?.fx?.(attack.impactTemplate || '', this.worldPosition)
      const p = this.worldPosition
      const hits = (this.scene?.physics as any)?.overlapSphere?.([p[0], p[1] + 0.5, p[2]], aoe, {
        ignore: this, filter: (node: Node) => !!node && node !== this && (node as any).team === 'player'
          && typeof (node as any).receiveHit === 'function' && (node as any).hurtboxActive !== false && !(node as any).isDead,
      }) ?? []
      for (const h of hits) this._hitPlayer(attack, h.node)
      return
    }
    openSwing(this._swing)
  }

  /** One frame of the active window: sweep the weapon's blade; the player is hit at most once. */
  private _stepSwing(): void {
    const weapon = this.currentWeapon() as any
    // Not in this enemy's own hand (no hand socket on its model): the blade is elsewhere, hit nothing.
    if (!wieldedBy(weapon, this)) return
    const blade = bladeCapsule(weapon)
    if (!blade) return
    const attack = this._attack as any
    const contact = stepSwing(this.scene?.physics, this._swing, blade, this, 'player', !!attack?.bounceOff)
    for (const t of contact.targets) this._hitPlayer(attack, t.node)
    if (contact.blockedAt) {
      closeSwing(this._swing)
      ;(this._gm as any)?.fx?.(weapon?.hitSparkTemplate || 'Hit Spark', contact.blockedAt)
    }
  }

  /**
   * An attack reached `target`. The damage is the ATTACK's — an enemy's moveset is tuned per move — and
   * the target takes it through its own receiveHit (where a rolling player's i-frames let it pass).
   */
  private _hitPlayer(attack: any, target: Node): boolean {
    const t = target as any
    if (!attack || typeof t?.receiveHit !== 'function') return false
    const landed = !!t.receiveHit(num(attack.damage, 50), num(attack.poiseDamage, 20), this)
    if (landed) (this._gm as any)?.sfx?.('Player Hit')
    return landed
  }

  private _fire(attack: any): void {
    if (!this._player) return
    const origin = this._castOrigin()
    const p = this._player.worldPosition
    const aim = [p[0] - origin[0], p[1] + 1.1 - origin[1], p[2] - origin[2]]
    const len = Math.hypot(aim[0], aim[1], aim[2]) || 1
    const count = Math.max(1, Math.round(num(attack.projectileCount, 1)))
    const spread = num(attack.spreadDeg, 0)
    for (let i = 0; i < count; i++) {
      const offset = count > 1 ? (i - (count - 1) / 2) * spread * Math.PI / 180 : 0
      const c = Math.cos(offset), s = Math.sin(offset)
      const dx = aim[0] / len, dz = aim[2] / len
      const dir = [dx * c + dz * s, aim[1] / len, -dx * s + dz * c]
      const bolt = this.scene?.instantiate(attack.projectileTemplate, { position: [origin[0], origin[1], origin[2]] }) as any
      if (bolt?.launch) bolt.launch(dir, num(attack.projectileSpeed, 12), num(attack.damage, 60), this.id)
    }
    ;(this._gm as any)?.sfx?.('Cast')
  }

  private _castOrigin(): number[] {
    const m = (this._model as any)?.getSocketWorldMatrix?.(this.castSocket)
    if (m) return [m[12], m[13], m[14]]
    const lp = this.lockPoint().worldPosition
    const f = this.worldForward
    return [lp[0] + f[0] * 0.6, lp[1], lp[2] + f[2] * 0.6]
  }

  // ----- reactions -------------------------------------------------------------------------------

  protected _react(state: string, clip: string, seconds: number): void {
    this._stopAction()
    this._enter(state)
    this._reactSeconds = seconds
    this._play(clip, 1)
    this._gap = Math.max(this._gap, 0.4)
  }

  protected _die(): void {
    if (this.isDead) return
    this.isDead = true
    this._stopAction()
    this._enter('dead')
    this._setBar(false)
    const brain = this._brain as any
    brain?.setBlackboard?.('dead', true)
    ;(this._aura as any)?.stop?.()
    if (this.dropWeaponOnDeath) this.dropWeapon()
    ;(this._model?.animator as any)?.setTrigger?.('Died')
    const gm = this._gm as any
    gm?.sfx?.('Enemy Death')
    gm?.onEnemyKilled?.(this)
    if (this.useRagdoll && this.deathSeconds > 0) this.after(this.deathSeconds, () => this._ragdoll())
    this.after(this.corpseSeconds, () => this.remove())
  }

  private _ragdoll(): void {
    const physics = this.scene?.physics as any
    if (!physics?.startRagdoll || !this._model) return
    try { physics.startRagdoll(this._model) }
    catch (e) { Logger.warn('Hollow Keep: ragdoll failed on ' + this.name + ': ' + e, 'Script') }
  }

  // ----- helpers ---------------------------------------------------------------------------------

  protected _enter(state: string): void {
    this.fightState = state
    this._stateTime = 0
    if (state !== 'attack') { this._attack = null; closeSwing(this._swing) }
    this.hurtboxActive = state !== 'dead' && state !== 'phase'
  }

  protected _still(intent: any): void {
    this.acceleration = 0
    this.facingMode = 'none'
    intent.move[0] = 0
    intent.move[1] = 0
  }

  private _turnToward(point: ArrayLike<number>, maxDegrees: number): void {
    const me = this.worldPosition
    const dx = point[0] - me[0]
    const dz = point[2] - me[2]
    if (Math.hypot(dx, dz) < 0.05) return
    const want = Math.atan2(dx, dz) * 180 / Math.PI
    const f = this.worldForward
    const have = Math.atan2(f[0], f[2]) * 180 / Math.PI
    let diff = (want - have) % 360
    if (diff > 180) diff -= 360
    else if (diff < -180) diff += 360
    this.setRotation([0, have + Math.max(-maxDegrees, Math.min(maxDegrees, diff)), 0])
  }

  protected _play(clip: string, speed: number): void {
    this._clip = clip
    this._clipLength = this._clipDuration(clip)
    const animator = this._model?.animator as any
    if (animator?.playAction && clip) animator.playAction(clip, { speed, blendIn: 0.1, blendOut: 0.2 })
  }

  protected _stopAction(): void {
    ;(this._model?.animator as any)?.stopAction?.(undefined, 0.12)
    this._clip = ''
  }

  private _clipDuration(name: string): number {
    const clip = this._findClip(name)
    if (!clip) return 0
    let end = 0
    for (const s of clip.samplers ?? []) if (s.input?.length) end = Math.max(end, s.input[s.input.length - 1])
    return end
  }

  private _clipHasEvent(name: string, event: string): boolean {
    return !!this._findClip(name)?.events?.some((e: any) => e.name === event)
  }

  private _findClip(name: string): any {
    const animations = (this._model?.model as any)?.animations
    return animations && name ? animations.find((a: any) => a.name === name) ?? null : null
  }

  private _setBar(show: boolean): void {
    const bar = this._healthBar as any
    if (bar && bar.visible !== show) bar.visible = show
  }

  private _find(root: Node, name: string): Node {
    for (const child of root.children) {
      if (child.name === name) return child
      const found = this._find(child, name)
      if (found) return found
    }
    return null
  }

  /** The animated model, however deep: a swapped-in model may sit under a holder node. */
  private _findModel(): ModelNode {
    const walk = (node: Node): ModelNode => {
      for (const child of node.children) {
        if (child.nodeType === 'model' && (child as any).animator) return child as ModelNode
        // Not into the weapons, the brain or the UI: none of them is this enemy's body.
        if (child.nodeType === 'controller' || child.name === 'Weapons' || child.nodeType === 'uiRoot') continue
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }

  private _rand(lo: number, hi: number): number {
    return lo + Math.random() * Math.max(0, hi - lo)
  }
}

import { ControllerNode, Node } from 'cleo'

/**
 * Hollow Keep — an enemy's brain script. Attach to the `Brain` child (the LAST child) of every enemy
 * template: a Controller node with Source: AI, Brain: Behaviour machine, linked to the type's AI graph
 * (`<Type> Brain.brain` under /AI).
 *
 * The GRAPH makes every decision — chase, close in, strafe, back off, attack, flinch, give up and walk
 * home — reading perception senses and the enemy's own fields. This script does the two things a graph
 * cannot express, in `onThink` (the last step of the control pass, so this frame's perception is in):
 *
 * 1. **Targeting.** The engine has no factions: perception offers every other Character, and auto-acquire
 *    would have enemies chase each other. So `autoAcquire` is off and the target is the nearest NOTICED
 *    character carrying `targetMarker` (the player sets `isPlayer`). A held target is kept until
 *    perception forgets it. `SoulsEnemy.receiveHit` also writes the attacker in directly, so an enemy hit
 *    from behind turns round.
 *
 * 2. **Home.** `goalPoint` is where the enemy spawned, which the graph's Return state paths back to.
 */
export default class SoulsEnemyBrainNode extends ControllerNode {
  public targetMarker: string = 'isPlayer'

  onThink(delta: number) {
    const pawn = this.possessed as any
    if (!pawn || pawn.isDead) return
    const key = this.targetKey

    const home = pawn.home ?? [0, 0, 0]
    this.goalPoint = [home[0], home[1], home[2]]
    const self = this.possessed.worldPosition

    const held = this.getBlackboard(key)
    const heldId = typeof held === 'string' && held ? held : null
    let bestId: string = null
    let bestDistance = Infinity
    let heldRemembered = false
    for (const sighting of this.sightings) {
      const candidate = this.scene?.getNodeById(sighting.id)
      if (!candidate || !candidate.getVariable(this.targetMarker)) continue
      if (sighting.id === heldId && sighting.timeSinceSeen <= this.perception.memorySpan) heldRemembered = true
      if (!sighting.noticed) continue
      const p = candidate.worldPosition
      const d = Math.hypot(p[0] - self[0], p[1] - self[1], p[2] - self[2])
      if (d < bestDistance) { bestDistance = d; bestId = sighting.id }
    }
    // A held target written by `receiveHit` or `awaken` survives even unseen for the memory span; a boss
    // never forgets the player inside its arena.
    const heldValid = !!heldId && (heldRemembered || pawn.isBoss || this._heldFresh(heldId))
    this.setBlackboard(key, bestId ?? (heldValid ? heldId : undefined))
  }

  /**
   * A target written in from outside perception (a hit from behind) has no sighting yet. Keep it while
   * it is within perception range, so the enemy turns and closes in rather than shrugging it off.
   */
  private _heldFresh(id: string): boolean {
    const node = this.scene?.getNodeById(id)
    if (!node || !this.possessed) return false
    const a = node.worldPosition
    const b = this.possessed.worldPosition
    return Math.hypot(a[0] - b[0], a[2] - b[2]) <= this.perception.range
  }
}

import { Logger, Node } from 'cleo'

/**
 * Hollow Keep — where an enemy lives. Attach to an empty node placed (and rotated) where the enemy
 * should stand; it instantiates `templateName` there.
 *
 * Enemies are TEMPLATES spawned at runtime rather than placed nodes, because resting at a bonfire must
 * bring every one of them back fresh — a placed node would need every field it ever changed restored by
 * hand. The spawn removes its previous instance (alive or corpse) and makes a new one.
 *
 * `isBossSpawn` marks the boss: it is created at the start and after a death mid-fight, but never by
 * resting, and never again once defeated. The manager is told about it so the HUD bar and the fog gate
 * can find the live boss.
 */
export default class SoulsEnemySpawnNode extends Node {
  public templateName: string = 'Hollow'
  public isBossSpawn: boolean = false
  /** Seconds after the scene starts before the first spawn — lets the level settle first. */
  public initialDelay: number = 0.1

  private _gm: Node = null
  private _live: Node = null

  onStart() {
    this._gm = this.findNode('GameManager')
    ;(this._gm as any)?.registerSpawn?.(this)
    this.after(this.initialDelay, () => this.respawnEnemy())
  }

  /** Remove whatever this spawn made before, and make a fresh one. */
  public respawnEnemy(): void {
    if (this._live && this.scene?.getNodeById(this._live.id)) {
      try { this._live.remove() } catch { /* already gone */ }
    }
    this._live = null
    const p = this.worldPosition
    const f = this.worldForward
    const yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    const enemy = this.scene?.instantiate(this.templateName, { position: [p[0], p[1], p[2]], rotation: [0, yaw, 0] })
    if (!enemy) {
      Logger.warn('Hollow Keep: spawn "' + this.name + '" found no template "' + this.templateName + '".', 'Script')
      return
    }
    this._live = enemy
    if (this.isBossSpawn) (this._gm as any)?.registerBoss?.(enemy)
  }

  /** The enemy this spawn made, or null. */
  public liveEnemy(): Node { return this._live }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — a magic bolt. Attach to the root of a projectile template (a plain node with the glowing
 * mesh, a light and a trail particle system beneath it). The firing enemy instantiates it at its hand and
 * calls `launch`.
 *
 * Flight is kinematic: every frame it moves `speed × delta` and sweeps that path twice, so a fast bolt
 * cannot tunnel through anything between two frames:
 *
 *   - a SPHERE of `radius` against the player's hurtbox (`physics.sweepSphere`). During a roll's i-frames
 *     the hurtbox is off (SoulsHitbox), so the sweep sees nothing and the bolt flies on through;
 *   - a ray against the world. Characters are skipped by the ray — the sphere handles them.
 *
 * On impact it spawns `impactTemplate` and removes itself; it also expires after `lifetime` seconds.
 */
export default class SoulsProjectileNode extends Node {
  public speed: number = 12
  public damage: number = 90
  public poiseDamage: number = 30
  public lifetime: number = 4
  /** The bolt's hitbox: a sphere of this radius swept along its flight. */
  public radius: number = 0.2
  public impactTemplate: string = 'Bolt Impact'

  private _dir: number[] = [0, 0, 1]
  private _age: number = 0
  private _live: boolean = false
  private _owner: string = ''
  private _gm: Node = null

  onStart() {
    this._gm = this.findNode('GameManager')
  }

  /** Fire along `dir` (normalised here). Called by SoulsEnemy right after instantiating. */
  public launch(dir: number[], speed: number, damage: number, ownerId: string): void {
    const len = Math.hypot(dir[0], dir[1], dir[2]) || 1
    this._dir = [dir[0] / len, dir[1] / len, dir[2] / len]
    this.speed = speed
    this.damage = damage
    this._owner = ownerId
    this._age = 0
    this._live = true
    this.setRotation([0, Math.atan2(this._dir[0], this._dir[2]) * 180 / Math.PI, 0])
  }

  onUpdate(delta: number) {
    if (!this._live) return
    this._age += delta
    if (this._age >= this.lifetime) { this._expire(false); return }

    const from = this.worldPosition
    const step = this.speed * delta
    const to = [from[0] + this._dir[0] * step, from[1] + this._dir[1] * step, from[2] + this._dir[2] * step]

    // The player's hurtbox, by a swept sphere. Off during i-frames, so a roll passes straight through.
    const physics = this.scene?.physics as any
    const hits = physics?.sweepSphere?.([from[0], from[1], from[2]], to, this.radius, {
      filter: (node: Node) => !!node && node.id !== this._owner && (node as any).team === 'player'
        && typeof (node as any).receiveHit === 'function' && (node as any).hurtboxActive !== false && !(node as any).isDead,
    }) ?? []
    for (const h of hits) {
      if ((h.node as any).receiveHit(this.damage, this.poiseDamage, this)) {
        this.setPosition([h.point[0], h.point[1], h.point[2]])
        this._expire(true)
        return
      }
    }

    // The world, by raycast. Characters are skipped — the sweep above handles them.
    const hit = physics?.raycast?.([from[0], from[1], from[2]], to, {
      reject: (owner: Node) => !!owner && (owner.id === this._owner || owner.nodeType === 'character'
        || owner === this || owner.isDescendantOf?.(this)),
    })
    if (hit) {
      this.setPosition([hit.point[0], hit.point[1], hit.point[2]])
      this._expire(true)
      return
    }
    this.setPosition(to)
  }

  private _expire(impact: boolean): void {
    this._live = false
    if (impact) {
      const gm = this._gm as any
      gm?.fx?.(this.impactTemplate, this.worldPosition)
      gm?.sfx?.('Bolt Impact')
    }
    this.remove()
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — a fire-and-forget effect. Attach to the root of an effect template (hit spark, bolt
 * impact, slam dust). On start it bursts every Particle System child, fades every point light child over
 * `lifetime`, and removes itself when that time is up.
 *
 * Swap the look by editing the template's particle systems; this script only owns the lifetime.
 */
export default class SoulsFxNode extends Node {
  public lifetime: number = 1.2
  /** Particles per child system on start. 0 leaves them to their own spawn rate / bursts. */
  public burstCount: number = 0

  private _age: number = 0
  private _lights: any[] = []
  private _intensities: number[] = []

  onStart() {
    this._age = 0
    const walk = (node: Node) => {
      for (const child of node.children) {
        const c = child as any
        if (child.nodeType === 'particleSystem') {
          // play(), not restart(): a fresh instance is already playing if its system plays on start,
          // and a restart would clear and prewarm it a second time on its first frame.
          c.play?.()
          if (this.burstCount > 0) c.burst?.(this.burstCount)
        }
        if (child.nodeType === 'light' && c.light) {
          this._lights.push(c.light)
          this._intensities.push(c.light.intensity)
        }
        walk(child)
      }
    }
    walk(this)
  }

  onUpdate(delta: number) {
    this._age += delta
    const k = Math.max(0, 1 - this._age / Math.max(0.01, this.lifetime))
    for (let i = 0; i < this._lights.length; i++) this._lights[i].intensity = this._intensities[i] * k
    if (this._age >= this.lifetime) this.remove()
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — an item lying in the world (the glowing corpse loot of the souls games). Attach to the
 * item's root; its children are the visuals (a mesh, a glow particle system, a light) and are hidden
 * once it is taken.
 *
 *   kind = 'souls'        adds `amount` souls
 *   kind = 'flaskShard'   +1 maximum Estus, and fills it
 *   kind = 'flaskCharge'  refills `amount` Estus, up to the maximum
 *
 * Pickups are one-shot for the whole session — resting does not bring them back. `hiddenUntilRevealed`
 * keeps one invisible and unreachable until something calls `reveal()` (the boss's reward does this).
 *
 * See SoulsBonfire for the interactable protocol.
 */
export default class SoulsPickupNode extends Node {
  public kind: string = 'souls'
  public amount: number = 200
  public itemName: string = 'Soul of a Lost Undead'
  public hiddenUntilRevealed: boolean = false
  public pickupClip: string = 'Souls_Pickup'
  public taken: boolean = false

  private _gm: Node = null

  onStart() {
    this._gm = this.findNode('GameManager')
    if (this.hiddenUntilRevealed) this.visible = false
    else (this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public reveal(): void {
    if (this.taken) return
    this.visible = true
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this.taken && this.visible }
  public promptText(player: Node): string { return 'Pick up ' + this.itemName }

  public interact(player: Node): void {
    if (this.taken) return
    const p = player as any
    const gm = this._gm as any
    this.taken = true
    p.playGesture?.(this.pickupClip, 0.8)
    if (this.kind === 'souls') p.addSouls?.(this.amount)
    // The flasks are the player's; it is asked to change them, never written to.
    else if (this.kind === 'flaskShard') p.addEstusFlask?.()
    else if (this.kind === 'flaskCharge') p.refillEstus?.(this.amount)
    gm?.notice?.('Picked up ' + this.itemName)
    gm?.sfx?.('Pickup')
    this.visible = false
    gm?.unregisterInteractable?.(this)
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — the bloodstain left where the player died, holding every soul they carried. Attach to
 * the root of the `Bloodstain` template; the GameManager instantiates it on death and sets `souls`.
 *
 * Touch it to get the souls back. Die again before you do and the manager replaces it with a new one —
 * the old souls are gone for good. See SoulsBonfire for the interactable protocol.
 */
export default class SoulsBloodstainNode extends Node {
  public souls: number = 0

  private _gm: Node = null
  private _taken: boolean = false

  onStart() {
    this._gm = this.findNode('GameManager')
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this._taken && !(player as any)?.isDead }
  public promptText(player: Node): string { return 'Retrieve souls' }

  public interact(player: Node): void {
    if (this._taken) return
    this._taken = true
    const p = player as any
    p.playGesture?.('Souls_Pickup', 0.8)
    p.addSouls?.(this.souls)
    const gm = this._gm as any
    gm?.onBloodstainRecovered?.(this)
    gm?.notice?.('Souls retrieved')
    this.remove()
  }
}

import { Node } from 'cleo'
import { clamp, num } from './SoulsMath'

/**
 * Hollow Keep — a blood decal on the ground. Attach to the root of a template whose children include
 * Decal nodes (`Blood Splat`, `Blood Drops`); the GameManager instantiates one where a hit lands and
 * sets `yaw` and `sizeScale` on it (see `bleed`).
 *
 * On its first frame it finds the floor below with a raycast, moves there and tilts so its decals
 * project straight into the surface — a ramp included — then gives them a random size. It removes
 * itself when there is no floor in reach: blood is never left hanging over a drop. After `lifetime`
 * it fades out over `fadeSeconds` and is removed.
 *
 * Placement waits for the first update rather than onStart, so the spawner's `yaw` and `sizeScale` are
 * in place whichever runs first; the decals stay invisible until then.
 */
export default class SoulsBloodSplatNode extends Node {
  /** Seconds before the splat is gone, its fade included. */
  public lifetime: number = 12
  /** The last part of `lifetime`, over which the decals fade out. */
  public fadeSeconds: number = 3
  /** Random size range, as a multiple of each decal's authored size. */
  public minSize: number = 0.65
  public maxSize: number = 1.25
  /** How far below the spawn point the floor may be. */
  public snapDown: number = 2.5
  /** Tilt onto sloped ground. Off, the splat lies flat and the decal's angle fade handles the slope. */
  public alignToSurface: boolean = true
  /** Set by the spawner. Which way the decal's +Z points, in degrees; NaN for a random turn. */
  public yaw: number = NaN
  /** Set by the spawner: a bigger hit leaves a bigger splat. */
  public sizeScale: number = 1

  private _age: number = 0
  private _placed: boolean = false
  private _decals: any[] = []
  private _sizes: number[][] = []

  onStart() {
    this._decals = this.children.filter(c => c.nodeType === 'decal')
    this._sizes = this._decals.map(d => [...d.size])
    for (const d of this._decals) d.opacity = 0
  }

  onUpdate(delta: number) {
    if (!this._placed) {
      this._placed = true
      if (!this._place()) { this.remove(); return }
    }
    this._age += delta
    const fade = Math.max(0.01, this.fadeSeconds)
    const k = clamp((this.lifetime - this._age) / fade, 0, 1)
    for (const d of this._decals) d.opacity = k
    if (this._age >= this.lifetime) this.remove()
  }

  /** Snap onto the floor below, turn, size. False when there is no floor in reach. */
  private _place(): boolean {
    // Spawned this frame, its world matrix may not have been computed yet: do it now, from the parent's.
    this.updateTransforms(this.parent ? this.parent.worldTransform : null)
    const p = this.worldPosition
    const physics = this.scene?.physics as any
    const hit = physics?.raycast?.([p[0], p[1] + 0.5, p[2]], [p[0], p[1] - this.snapDown, p[2]], {
      reject: (owner: Node) => isCharacterPart(owner),
    })
    if (!hit) return false

    const yaw = Number.isFinite(this.yaw) ? this.yaw : Math.random() * 360
    const n = hit.normal
    // Local +Y onto the surface normal: rotations compose Ry(yaw)·Rx(pitch), and Rx(p)·(0,1,0) turned by
    // Ry(y) is (sin p sin y, cos p, sin p cos y). A floor has no tilt, so its yaw stays free for the turn.
    const tilt = this.alignToSurface ? Math.acos(clamp(n[1], -1, 1)) * 180 / Math.PI : 0
    const rotation: [number, number, number] = tilt > 2
      ? [tilt, Math.atan2(n[0], n[2]) * 180 / Math.PI, 0]
      : [0, yaw, 0]
    this.setPosition([hit.point[0], hit.point[1], hit.point[2]])
    this.setRotation(rotation)

    const scale = num(this.sizeScale, 1) * (this.minSize + Math.random() * Math.max(0, this.maxSize - this.minSize))
    this._decals.forEach((d, i) => {
      const s = this._sizes[i]
      // Height stays: it is how far the projection reaches, not how big the splat looks.
      d.size = [s[0] * scale, s[1], s[2] * scale]
      d.opacity = 1
    })
    return true
  }
}

/** A character, or anything inside one (a ragdolled limb): blood lands on the floor, not on a body. */
function isCharacterPart(owner: Node): boolean {
  for (let n: Node = owner; n; n = n.parent) if (n.nodeType === 'character') return true
  return false
}

import { Node } from 'cleo'

/**
 * Hollow Keep — a readable message on the ground: tutorial hints and lore. Attach to the message's root
 * (a glowing glyph mesh and a few motes). Interact shows `title` and `text` in the HUD's message panel,
 * which closes when the player presses Interact again or walks away.
 *
 * `\n` in `text` is a line break. See SoulsBonfire for the interactable protocol.
 */
export default class SoulsMessageNode extends Node {
  public title: string = 'A message'
  public text: string = 'Try rolling.'
  public hiddenUntilRevealed: boolean = false

  private _gm: Node = null

  onStart() {
    this._gm = this.findNode('GameManager')
    if (this.hiddenUntilRevealed) this.visible = false
    else (this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public reveal(): void {
    this.visible = true
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return this.visible }
  public promptText(player: Node): string { return 'Read message' }

  public interact(player: Node): void {
    const gm = this._gm as any
    gm?.showMessage?.(this.title, this.text.split('\\n').join('\n'), this)
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — a lever that opens a door elsewhere (the shortcut back to the bonfire). Attach to the
 * lever's root; a child named `Handle` is swung through `swingDegrees` about X when pulled.
 *
 * One use. `doorName` names a node carrying SoulsDoor. See SoulsBonfire for the interactable protocol.
 */
export default class SoulsLeverNode extends Node {
  public doorName: string = 'Shortcut Gate'
  public swingDegrees: number = 70
  public swingSeconds: number = 0.6
  public pulled: boolean = false

  private _gm: Node = null
  private _handle: Node = null
  private _t: number = -1
  private _rest: number[] = [0, 0, 0]

  onStart() {
    this._gm = this.findNode('GameManager')
    this._handle = this.getChildByName('Handle')[0] ?? null
    if (this._handle) { const r = this._handle.rotation; this._rest = [r[0], r[1], r[2]] }
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this.pulled }
  public promptText(player: Node): string { return 'Pull lever' }

  public interact(player: Node): void {
    if (this.pulled) return
    this.pulled = true
    this._t = 0
    ;(player as any).playGesture?.('Souls_Interact', 0.9)
    const gm = this._gm as any
    gm?.sfx?.('Lever')
    const door = this.findNode(this.doorName) as any
    if (door?.openDoor) this.after(this.swingSeconds, () => door.openDoor())
    gm?.unregisterInteractable?.(this)
  }

  onUpdate(delta: number) {
    if (this._t < 0 || !this._handle) return
    this._t = Math.min(1, this._t + delta / Math.max(0.01, this.swingSeconds))
    const k = this._t * this._t * (3 - 2 * this._t)
    this._handle.setRotation([this._rest[0] + this.swingDegrees * k, this._rest[1], this._rest[2]])
    if (this._t >= 1) this._t = -1
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — a door or portcullis that slides open. Attach to a node with a STATIC box body at the
 * scene root (or under an untransformed group); its visual is the node's own model or a child.
 *
 * Opened by a lever (`openDoor()`). From the locked side it is an interactable that only says why it
 * will not open — the souls convention that tells the player a shortcut exists. "Locked side" is the
 * side the node's local +Z points AWAY from when `lockedFromFront` is false, and toward when true.
 *
 * The slide moves the whole node, body included, so nothing else needs to know the door moved.
 */
export default class SoulsDoorNode extends Node {
  /** Offset from the closed position when fully open, in world metres. */
  public openOffset: [number, number, number] = [0, 4.2, 0]
  public openSeconds: number = 1.6
  public isOpen: boolean = false
  public lockedText: string = 'Opens from the other side'
  public lockedFromFront: boolean = false

  private _gm: Node = null
  private _closed: number[] = [0, 0, 0]
  private _t: number = 0
  private _opening: boolean = false

  onStart() {
    this._gm = this.findNode('GameManager')
    const p = this.position
    this._closed = [p[0], p[1], p[2]]
    if (this.isOpen) this._apply(1)
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean {
    if (this.isOpen || this._opening || !player) return false
    const p = player.worldPosition
    const me = this.worldPosition
    const f = this.worldForward
    const front = (p[0] - me[0]) * f[0] + (p[2] - me[2]) * f[2] > 0
    return front === this.lockedFromFront
  }

  public promptText(player: Node): string { return 'Examine' }

  public interact(player: Node): void {
    ;(this._gm as any)?.notice?.(this.lockedText)
  }

  public openDoor(): void {
    if (this.isOpen || this._opening) return
    this._opening = true
    this._t = 0
    ;(this._gm as any)?.sfx?.('Door')
  }

  onUpdate(delta: number) {
    if (!this._opening) return
    this._t = Math.min(1, this._t + delta / Math.max(0.01, this.openSeconds))
    this._apply(this._t * this._t * (3 - 2 * this._t))
    if (this._t >= 1) {
      this._opening = false
      this.isOpen = true
      ;(this._gm as any)?.notice?.('A shortcut has opened')
    }
  }

  private _apply(k: number): void {
    this.setPosition([
      this._closed[0] + this.openOffset[0] * k,
      this._closed[1] + this.openOffset[1] * k,
      this._closed[2] + this.openOffset[2] * k,
    ])
  }
}

import { Node } from 'cleo'

/**
 * Hollow Keep — the fog wall in front of the boss. Attach to a node at the arena's mouth that carries a
 * STATIC box body (the blocker), with its local +Z pointing INTO the arena.
 *
 *   Fog Gate          this script + box body
 *   ├── FogWall       the translucent sheet — any mesh
 *   └── Fog           particle system, the drifting fog
 *
 *   closed    blocks both ways. From OUTSIDE, Interact: "Traverse the white fog". The player is lined
 *             up, walks through over `walkSeconds` with i-frames while the body is a ghost, and the
 *             fight starts on the far side.
 *   fight     blocks both ways, no prompt — there is no leaving.
 *   gone      the boss is dead: the fog dissolves for good.
 *
 * A death mid-fight resets it to `closed` (the manager calls `resetGate`).
 *
 * The prompt comes from the gate's TRIGGER volume (a box spanning both sides of the wall): standing in it
 * offers "Traverse", and `canInteract` only allows it from outside. A separate `Boss Arena` zone (a
 * trigger with the `isBossArena` variable) starts the fight if the player ever gets inside without
 * walking through.
 */
export default class SoulsFogGateNode extends Node {
  /** Metres in front of the gate (outside) the player is lined up at before walking. */
  public entryDistance: number = 1.1
  public walkDistance: number = 2.8
  public walkSeconds: number = 1.5
  public isFogGate: boolean = true
  /** 'closed' | 'fight' | 'gone' */
  public gateState: string = 'closed'

  private _gm: Node = null
  private _fog: Node = null
  private _wall: Node = null
  private _fade: number = -1

  onStart() {
    this._gm = this.findNode('GameManager')
    this._fog = this.getChildByName('Fog')[0] ?? null
    this._wall = this.getChildByName('FogWall')[0] ?? null
    this._solid(true)
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean {
    if (this.gateState !== 'closed' || !player) return false
    return this._side(player.worldPosition) < 0
  }

  public promptText(player: Node): string { return 'Traverse the white fog' }

  public interact(player: Node): void {
    const p = player as any
    if (!p.walkThroughFog) return
    const me = this.worldPosition
    const f = this._forward()
    const start = [me[0] - f[0] * this.entryDistance, player.worldPosition[1], me[2] - f[2] * this.entryDistance]
    const yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    this._solid(false)
    p.walkThroughFog(start, yaw, this.walkDistance, this.walkSeconds)
    ;(this._gm as any)?.sfx?.('Fog')
    this.after(this.walkSeconds + 0.05, () => {
      this._solid(true)
      this.gateState = 'fight'
      ;(this._gm as any)?.startBossFight?.(this)
    })
  }

  /** The boss died: fade the fog out and leave the way open. */
  public dissolve(): void {
    this.gateState = 'gone'
    this._solid(false)
    ;(this._fog as any)?.stop?.()
    this._fade = 0
  }

  /** The player died mid-fight. */
  public resetGate(): void {
    if (this.gateState === 'gone') return
    this.gateState = 'closed'
    this._solid(true)
  }

  onUpdate(delta: number) {
    if (this._fade < 0) return
    this._fade += delta
    const wall = this._wall as any
    if (wall && this._fade > 1.2 && wall.visible) wall.visible = false
    if (this._fade > 1.2) this._fade = -1
  }

  /** Signed distance of a point along the gate's forward: negative outside, positive inside. */
  private _side(point: ArrayLike<number>): number {
    const me = this.worldPosition
    const f = this._forward()
    return (point[0] - me[0]) * f[0] + (point[2] - me[2]) * f[2]
  }

  private _forward(): number[] {
    const f = this.worldForward
    const len = Math.hypot(f[0], f[2]) || 1
    return [f[0] / len, 0, f[2] / len]
  }

  private _solid(on: boolean): void {
    const body = this.body as any
    if (body) body.simulatePhysics = on
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the PLAYER's HUD. Attach to the `HUD` node, a screen-space UI Root that is a CHILD of
 * the player (in the Player template): the HUD belongs to the character it shows, and reads that
 * character — its parent — not some node found by name. A second player would bring its own HUD.
 *
 * One script for the whole HUD. It finds its widgets by NAME once (missing ones are skipped, so you can
 * restyle or rebuild the HUD freely as long as the names stay) and writes them every frame from its
 * owner's public fields:
 *
 *   Health, HealthLag        uiProgressBar   HP, and the yellow "damage taken" bar that drains behind it
 *   Stamina                  uiProgressBar
 *   Estus                    uiText          flask count
 *   Weapon                   uiText          weapon in hand
 *   Souls, SoulsGain         uiText          souls held, and the +N popup
 *   Prompt / PromptText      uiPanel/uiText  "E  Rest at bonfire" — hidden when there is nothing to do
 *   Notice                   uiText          one-line messages ("Picked up ..."), fading
 *   Message / MessageTitle / MessageBody     the readable-message panel
 *
 * The boss bar is not here: it belongs to the boss (SoulsBossBar, inside the Hollow Warden template).
 *
 * Bars grow with their maximum (`pxPerHp`, `pxPerStamina`), so levelling Vigor visibly lengthens the bar.
 */
export default class SoulsHudNode extends UIRootNode {
  public pxPerHp: number = 0.75
  public pxPerStamina: number = 2.4
  public minBarWidth: number = 160
  public maxBarWidth: number = 900
  public noticeSeconds: number = 2.6
  /** Key shown in front of the interaction prompt. */
  public interactKey: string = 'E'

  private _player: Node = null
  private _w: any = {}
  private _barLeft: number = 48
  private _noticeAge: number = 99
  private _message: Node = null
  private _messageAge: number = 0

  onStart() {
    // The owner: the nearest ancestor that is a fighter (the Player the HUD is a child of).
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._player = n; break }
    for (const name of ['Health', 'HealthLag', 'HealthBack', 'Stamina', 'StaminaBack', 'Estus', 'Weapon', 'Souls',
      'SoulsGain', 'Prompt', 'PromptText', 'Notice', 'Message', 'MessageTitle', 'MessageBody']) {
      this._w[name] = this._find(name)
    }
    const health = this._w.Health as any
    if (health) this._barLeft = health.offsetMin[0]
    this._show('Message', false)
    this._show('Prompt', false)
    this._text('Notice', '')
    this._text('SoulsGain', '')
  }

  onUpdate(delta: number) {
    const p = this._player as any
    this._noticeAge += delta
    this._messageAge += delta

    if (p) {
      this._bar('Health', p.hp, p.maxHp)
      this._bar('HealthLag', p.hp, p.maxHp)
      this._width(['Health', 'HealthLag', 'HealthBack'], p.maxHp * this.pxPerHp)
      this._bar('Stamina', p.stamina, p.maxStamina)
      this._width(['Stamina', 'StaminaBack'], p.maxStamina * this.pxPerStamina)
      this._text('Estus', 'Estus Flask  ' + (p.estus ?? 0) + ' / ' + (p.estusMax ?? 0))
      this._text('Weapon', p.weaponName ?? '')
      this._text('Souls', String(Math.round(p.souls ?? 0)))
      this._text('SoulsGain', p.soulsGainAge < 2 && p.lastSoulsGain > 0 ? '+' + p.lastSoulsGain : '')

      const prompt = p.interactPrompt ?? ''
      this._show('Prompt', !!prompt && !this._message)
      if (prompt) this._text('PromptText', this.interactKey + '   ' + prompt)
    }

    if (this._noticeAge > this.noticeSeconds) this._text('Notice', '')

    // A message closes when the player walks out of its source's zone (closeMessageFrom), or dies.
    if (this._message && p?.isDead) this._closeMessage()
  }

  /** The character this HUD shows. */
  public get owner(): Node { return this._player }

  public showNotice(text: string): void {
    this._text('Notice', text)
    this._noticeAge = 0
  }

  /** Show a message; showing the SAME source again closes it (Interact toggles). */
  /** The player left `source`'s trigger zone: close its message if it is the one showing. */
  public closeMessageFrom(source: Node): void {
    if (this._message && this._message === source) this._closeMessage()
  }

  public showMessage(title: string, body: string, source: Node): void {
    if (this._message && this._message === source && this._messageAge > 0.15) { this._closeMessage(); return }
    this._message = source
    this._messageAge = 0
    this._text('MessageTitle', title)
    this._text('MessageBody', body)
    this._show('Message', true)
  }

  private _closeMessage(): void {
    this._message = null
    this._show('Message', false)
  }

  private _bar(name: string, value: number, max: number): void {
    const bar = this._w[name] as UIProgressBarNode
    if (!bar) return
    if (bar.max !== max) bar.max = Math.max(1, max)
    bar.value = Math.max(0, value)
  }

  private _width(names: string[], px: number): void {
    const width = Math.max(this.minBarWidth, Math.min(this.maxBarWidth, px))
    for (const name of names) {
      const node = this._w[name] as any
      if (!node) continue
      const right = node.offsetMin[0] + width
      if (Math.abs(node.offsetMax[0] - right) > 0.5) node.offsetMax = [right, node.offsetMax[1]]
    }
  }

  private _text(name: string, value: string): void {
    const node = this._w[name] as UITextNode
    if (node && node.text !== value) node.text = value
  }

  private _show(name: string, on: boolean): void {
    const node = this._w[name] as any
    if (node && node.visible !== on) node.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — a boss's health bar. Attach to a screen-space UI Root that is a CHILD of the boss (in the
 * Hollow Warden template): the bar belongs to the boss it shows and reads that boss — its owner — every
 * frame. It shows while the boss is awake and alive, so it comes up when the fight starts and goes when
 * the boss falls. A second boss template brings its own bar; nothing in the scene has to change.
 *
 *   BossName                 uiText          the owner's `displayName`
 *   BossHealth, BossLag      uiProgressBar   HP, and the yellow bar that drains behind it
 */
export default class SoulsBossBarNode extends UIRootNode {
  private _owner: Node = null
  private _w: any = {}

  onStart() {
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._owner = n; break }
    for (const name of ['Bar', 'BossName', 'BossHealth', 'BossLag']) this._w[name] = this._find(name)
    this._show(false)
  }

  onUpdate(delta: number) {
    const boss = this._owner as any
    const on = !!boss && boss.isAwake && !boss.isDead && boss.fightState !== 'dormant'
    this._show(on)
    if (!on) return
    const hp = Math.max(0, boss.hp ?? 0), max = Math.max(1, boss.maxHp ?? 1)
    const name = this._w.BossName as UITextNode
    const label = boss.displayName ?? boss.name ?? ''
    if (name && name.text !== label) name.text = label
    for (const key of ['BossHealth', 'BossLag']) {
      const bar = this._w[key] as UIProgressBarNode
      if (!bar) continue
      if (bar.max !== max) bar.max = max
      bar.value = hp
    }
  }

  /** The boss this bar shows. */
  public get owner(): Node { return this._owner }

  private _show(on: boolean): void {
    const bar = this._w.Bar as any
    if (bar && bar.visible !== on) bar.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Node, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the big centre-screen banners: YOU DIED, BONFIRE LIT, VICTORY ACHIEVED. Attach to the
 * `Banner` node, a screen-space UI Root authored hidden, with a `Band` panel and a `BannerText` text.
 *
 * Its own root rather than part of the HUD, because setting `visible` on a node writes every descendant —
 * revealing a panel nested in the HUD would force every HUD widget visible with it.
 *
 * `showBanner(text, kind)` fades in, holds, and fades out. `kind` picks the colour: `red` (death — held
 * until `hideBanner`, which the respawn calls) or `gold`.
 */
export default class SoulsBannerNode extends UIRootNode {
  public fadeIn: number = 0.6
  public hold: number = 2.2
  public fadeOut: number = 1
  public redColor: [number, number, number] = [0.72, 0.08, 0.06]
  public goldColor: [number, number, number] = [0.96, 0.82, 0.46]

  private _text: UITextNode = null
  private _age: number = -1
  private _sticky: boolean = false

  onStart() {
    this._text = this._find('BannerText') as UITextNode
    this.visible = false
  }

  public showBanner(text: string, kind: string): void {
    const c = kind === 'red' ? this.redColor : this.goldColor
    if (this._text) {
      this._text.text = text
      this._text.tint = [c[0], c[1], c[2], 1]
    }
    this._sticky = kind === 'red'
    this._age = 0
    this.opacity = 0
    this.visible = true
  }

  public hideBanner(): void {
    if (this._age < 0) return
    this._sticky = false
    this._age = Math.max(this._age, this.fadeIn + this.hold)
  }

  onUpdate(delta: number) {
    if (this._age < 0) return
    this._age += delta
    const t = this._age
    let a = 1
    if (t < this.fadeIn) a = t / this.fadeIn
    else if (this._sticky) a = 1
    else if (t > this.fadeIn + this.hold) a = 1 - (t - this.fadeIn - this.hold) / this.fadeOut
    a = Math.max(0, Math.min(1, a))
    if (Math.abs(this.opacity - a) > 0.004) this.opacity = a
    if (!this._sticky && t > this.fadeIn + this.hold + this.fadeOut) {
      this._age = -1
      this.visible = false
    }
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the level-up menu shown while resting at a bonfire. Attach to the `BonfireMenu` node, a
 * screen-space UI Root authored hidden.
 *
 *   Card
 *     Title, LevelText, SoulsText, CostText, Derived, Help       uiText
 *     Row_Vigor / Row_Endurance / Row_Strength / Row_Dexterity     uiStack rows, each with
 *        Label (uiText)  Minus (uiButton)  Value (uiText)  Plus (uiButton)
 *     Confirm, Leave                                                uiButton
 *
 * Points are allocated as PENDING and cost nothing until Confirm, so the player can try a build and back
 * out. Each point costs the souls for one more level, priced by the player's own `levelCost`, so the total
 * of several points is the sum of consecutive levels. Every number shown comes from its owner: HP and
 * stamina from the player's curves, attack rating from each weapon.
 *
 * Keyboard/gamepad (the UI map): Navigate up/down picks a stat, left/right removes/adds a point, Submit
 * confirms, Cancel leaves. The mouse can click every button. The Gameplay map is disabled while open, so
 * the same keys do not also move the character.
 */
const STATS = ['vigor', 'endurance', 'strength', 'dexterity']

export default class SoulsBonfireMenuNode extends UIRootNode {
  public repeatDelay: number = 0.35
  public repeatRate: number = 0.09
  public selectedTint: [number, number, number, number] = [0.85, 0.65, 0.3, 0.35]
  public rowTint: [number, number, number, number] = [1, 1, 1, 0.04]
  public isOpen: boolean = false

  private _gm: Node = null
  private _player: Node = null
  private _pending: number[] = [10, 10, 10, 10]
  private _selected: number = 0
  private _navHeld: number = 0
  private _navRepeat: number = 0
  private _navLast: number[] = [0, 0]
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const rows = ['Row_Vigor', 'Row_Endurance', 'Row_Strength', 'Row_Dexterity']
    rows.forEach((name, i) => {
      const row = this._find(name)
      if (!row) return
      const minus = this._find('Minus', row) as UIButtonNode
      const plus = this._find('Plus', row) as UIButtonNode
      if (minus) minus.onPress = () => { this._selected = i; this._adjust(-1) }
      if (plus) plus.onPress = () => { this._selected = i; this._adjust(1) }
    })
    const confirm = this._find('Confirm') as UIButtonNode
    if (confirm) confirm.onPress = () => this._confirm()
    const leave = this._find('Leave') as UIButtonNode
    if (leave) leave.onPress = () => this.close()
  }

  /** Called by the manager when the player rests. */
  public open(gm: Node, player: Node, bonfire: Node): void {
    this._gm = gm
    this._player = player
    this._resetPending()
    this._selected = 0
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    this._refresh()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    ;(this._gm as any)?.leaveBonfire?.()
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return

    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    const dx = Math.abs(nav[0]) > 0.5 ? Math.sign(nav[0]) : 0
    const fresh = dy !== this._navLast[1] || dx !== this._navLast[0]
    this._navLast = [dx, dy]
    let step = false
    if (dx || dy) {
      if (fresh) { step = true; this._navHeld = 0; this._navRepeat = 0 }
      else {
        this._navHeld += delta
        if (this._navHeld > this.repeatDelay) {
          this._navRepeat += delta
          if (this._navRepeat >= this.repeatRate) { this._navRepeat = 0; step = true }
        }
      }
    }
    if (step) {
      // Navigate Y is positive UP; rows run top to bottom.
      if (dy) this._selected = (this._selected - dy + 4) % 4
      if (dx) this._adjust(dx)
      this._refresh()
    }

    if (Input.started('Submit')) this._confirm()
    if (Input.started('Cancel')) this.close()
  }

  // ----- the maths --------------------------------------------------------------------------------

  /** Souls to buy every pending point, from the player's CURRENT level. */
  public pendingCost(): number {
    const p = this._player as any
    if (!p?.levelFor) return 0
    const from = p.level
    const to = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    let cost = 0
    for (let l = from; l < to; l++) cost += p.levelCost(l)
    return cost
  }

  private _adjust(delta: number): void {
    const p = this._player as any
    if (!p) return
    const key = STATS[this._selected]
    const floor = p[key]
    const next = this._pending[this._selected] + delta
    if (next < floor || next > 99) return
    const before = this._pending[this._selected]
    this._pending[this._selected] = next
    if (delta > 0 && this.pendingCost() > (p.souls ?? 0)) {
      this._pending[this._selected] = before
      ;(this._gm as any)?.sfx?.('Menu Deny')
      return
    }
    ;(this._gm as any)?.sfx?.('Menu Tick')
    this._refresh()
  }

  private _confirm(): void {
    const p = this._player as any
    if (!p) return
    const cost = this.pendingCost()
    if (cost <= 0) return
    if (p.applyLevelUp?.(this._pending[0], this._pending[1], this._pending[2], this._pending[3], cost)) {
      ;(this._gm as any)?.sfx?.('Level Up')
      ;(this._gm as any)?.notice?.('Level up!')
    }
    this._resetPending()
    this._refresh()
  }

  private _resetPending(): void {
    const p = this._player as any
    this._pending = STATS.map(k => (p ? p[k] : 10))
  }

  private _refresh(): void {
    const p = this._player as any
    if (!p?.levelFor) return
    const level = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    const cost = this.pendingCost()
    this._set('LevelText', 'Level  ' + p.level + (level !== p.level ? '  ->  ' + level : ''))
    this._set('SoulsText', 'Souls  ' + p.souls + (cost ? '  ->  ' + (p.souls - cost) : ''))
    this._set('CostText', 'Next level  ' + p.levelCost(level) + ' souls')

    const labels = ['Vigor', 'Endurance', 'Strength', 'Dexterity']
    labels.forEach((label, i) => {
      const row = this._find('Row_' + label) as any
      if (!row) return
      const changed = this._pending[i] !== p[STATS[i]]
      const value = this._find('Value', row) as UITextNode
      if (value) value.text = String(this._pending[i]) + (changed ? ' *' : '')
      const tint = i === this._selected ? this.selectedTint : this.rowTint
      row.tint = [tint[0], tint[1], tint[2], tint[3]]
    })

    const weapons: Node[] = p.weapons?.() ?? []
    const ar = weapons.map(w => (w as any).displayName + ' ' + ((w as any).attackRating?.(this._pending[2], this._pending[3]) ?? 0))
    this._set('Derived', 'HP ' + p.hpForVigor(this._pending[0]) + '    Stamina ' + p.staminaForEndurance(this._pending[1])
      + '\nAttack  ' + ar.join('   '))
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node && node.text !== text) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(root)
  }
}

import type { Node } from 'cleo'

/**
 * Hollow Keep — shared maths for the Souls* scripts. A script MODULE: it exports helpers and is never
 * attached to a node. Every script that needs these imports them by path:
 *
 *   import { num, yawTo, angleDiff } from './SoulsMath'        relative to the importing script
 *   import { num } from '@/Scripts/SoulsMath'                   or from the project root
 *
 * Evaluated once per game and shared, so it holds no per-node state.
 *
 * Angles follow the engine's convention: yaw in degrees, 0 is +Z, counter-clockwise positive (the
 * character's RIGHT is a negative turn).
 */

/** `value` if it is a finite number, else `fallback` — for reading tunables off other scripts' nodes. */
export function num(value: any, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback
}

export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v
}

/** Distance on the ground plane, ignoring height. */
export function planarDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.hypot(b[0] - a[0], b[2] - a[2])
}

/** World yaw in degrees from `a` toward `b`. */
export function yawTo(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.atan2(b[0] - a[0], b[2] - a[2]) * 180 / Math.PI
}

/** Signed shortest difference `a - b` in degrees, in (-180, 180]. */
export function angleDiff(a: number, b: number): number {
  let d = (a - b) % 360
  if (d > 180) d -= 360
  else if (d <= -180) d += 360
  return d
}

/** The yaw a node faces, from its world forward. */
export function forwardYaw(node: Node): number {
  const f = node.worldForward
  return Math.atan2(f[0], f[2]) * 180 / Math.PI
}

/**
 * How much a stat adds to a weapon that scales with it fully: 0 at 10, 0.6 at 30, 0.9 at 50, then a
 * quarter of a percent per point. Soft caps are the whole reason a build has to choose.
 */
export function statBonus(stat: number): number {
  if (stat <= 10) return 0
  if (stat <= 30) return (stat - 10) / 20 * 0.6
  if (stat <= 50) return 0.6 + (stat - 30) / 20 * 0.3
  return 0.9 + (stat - 50) * 0.0025
}

import { resolveSocketOwner } from 'cleo'
import type { Node } from 'cleo'
import { num } from './SoulsMath'

/**
 * Hollow Keep — hitboxes and hurtboxes. A script MODULE (never attached to a node), shared by the
 * player, the enemies and the bolt.
 *
 * ## Hurtboxes
 *
 * A character's hurtbox is its physics capsule — the body it already walks with. Nothing extra to author.
 * A character whose `hurtboxActive` is false is invisible to every attack: that is what i-frames ARE. A
 * roll does not make the player "ignore" a hit; for those frames the blade passes through nothing.
 *
 * ## Hitboxes
 *
 * A weapon's hitbox is a capsule along its blade, from `bladeStart` to `bladeEnd` with `bladeRadius`,
 * measured in the weapon's `Mesh` child space — the same space the blade's boxes are modelled in, so
 * re-gripping or swapping the mesh carries the hitbox with it. While an attack's ACTIVE WINDOW is open
 * (clip events `hit` → `hitEnd`), the blade is swept every frame from where it was last frame to where it
 * is now (`physics.sweepCapsule`), so a fast swing cannot pass through a target between two frames, and
 * each target is hit once per swing.
 *
 * ## Swing blockers
 *
 * A solid body whose node has the variable `blocksSwings` = true (walls, pillars, gates) stops a swing
 * that reaches it before any enemy: the blade bounces, and the attacker recoils. Floors are not swing
 * blockers, so an overhead never bounces off the ground.
 */

export interface Capsule { a: number[]; b: number[]; radius: number }

/** The swing state an attacker keeps between frames. Reset with `openSwing` when a window opens. */
export interface Swing {
  /** Last frame's blade, or null on the window's first frame. */
  prev: Capsule | null
  /** Every node this swing has already damaged. */
  hit: Node[]
  open: boolean
}

export function newSwing(): Swing { return { prev: null, hit: [], open: false } }

export function openSwing(swing: Swing): void { swing.prev = null; swing.hit.length = 0; swing.open = true }
export function closeSwing(swing: Swing): void { swing.prev = null; swing.open = false }

/** Transform a point by a column-major 4x4 matrix. */
function transformPoint(m: ArrayLike<number>, p: ArrayLike<number>): number[] {
  const x = p[0], y = p[1], z = p[2]
  return [m[0] * x + m[4] * y + m[8] * z + m[12], m[1] * x + m[5] * y + m[9] * z + m[13], m[2] * x + m[6] * y + m[10] * z + m[14]]
}

/**
 * The weapon's blade capsule in world space, or null when it has none. Read from the `Mesh` child's world
 * transform (falling back to the weapon node itself), so the radius scales with a big enemy's weapon.
 */
export function bladeCapsule(weapon: Node): Capsule | null {
  if (!weapon) return null
  // A script field (SoulsWeapon), or a plain node VARIABLE (a script-less weapon in a user's own project).
  const field = (name: string) => (weapon as any)[name] ?? (weapon as any).getVariable?.(name)
  const start = field('bladeStart'), end = field('bladeEnd')
  if (!start || !end || start.length < 3 || end.length < 3) return null
  const space = weapon.getChildByName?.('Mesh')?.[0] ?? weapon
  const m = space.worldTransform as ArrayLike<number>
  const scale = Math.hypot(m[0], m[1], m[2])
  return { a: transformPoint(m, start), b: transformPoint(m, end), radius: num(field('bladeRadius'), 0.1) * scale }
}

function isWithin(node: Node, ancestor: Node): boolean {
  for (let n: Node = node; n; n = n.parent) if (n === ancestor) return true
  return false
}

/**
 * Whether `weapon` is actually in `wielder`'s hand: pinned to a socket that resolves on a model INSIDE the
 * wielder. A swing is only swept when it is.
 *
 * The safety net under a model swap: a character whose new rig has no hand socket used to have its weapon
 * ride whichever model in the scene did have one, and its swings were swept there — a sword hurting a
 * knight across the level, enemy blades never reaching the player. A weapon not in its wielder's hand now
 * simply hits nothing.
 */
export function wieldedBy(weapon: Node, wielder: Node): boolean {
  if (!weapon || !wielder) return false
  const attachment = (weapon as any).socketAttachment
  // Unpinned (a user's own weapon parented straight to a bone node): it is the wielder's if it is under it.
  if (!attachment) return isWithin(weapon, wielder)
  const owner: any = resolveSocketOwner(weapon, attachment, (id: string) => weapon.scene?.getNodeById(id) ?? null)
  return !!owner && isWithin(owner, wielder) && (owner.socketNames ?? []).includes(attachment.socket)
}

/**
 * Whether `node` is a live hurtbox `attacker` may hit. `kind` is the TEAM being attacked (a fighter's
 * `team` field, SoulsCharacter): the player's blade hits 'enemy', an enemy's hits 'player'.
 */
export function isHurtbox(node: Node, attacker: Node, kind: 'player' | 'enemy'): boolean {
  const n = node as any
  if (!node || node === attacker || n.isDead || n.hurtboxActive === false || n.spawned === false) return false
  return n.team === kind && typeof n.receiveHit === 'function'
}

/** Whether a body stops a swing: solid, and its node opted in with the `blocksSwings` variable. */
export function blocksSwings(node: Node, body: any): boolean {
  if (!node || !body || body.isTrigger || body.collisionResponse === false) return false
  return !!(node as any).getVariable?.('blocksSwings')
}

export interface SwingContact {
  /** New hurtboxes touched this frame, in the order the blade reached them. */
  targets: { node: Node; point: number[] }[]
  /** Where the blade met a swing blocker BEFORE any of those targets, or null. */
  blockedAt: number[] | null
}

/**
 * Advance a swing by one frame: sweep the blade from last frame's pose to `blade`, and report the new
 * targets and whether a blocker got in the way first. Targets already hit this swing are not reported
 * again. With `bounces` false, blockers are ignored (a heavy slam ploughs on through).
 */
export function stepSwing(physics: any, swing: Swing, blade: Capsule, attacker: Node,
  kind: 'player' | 'enemy', bounces: boolean): SwingContact {
  const result: SwingContact = { targets: [], blockedAt: null }
  if (!physics || !swing.open || !blade) return result
  const prev = swing.prev ?? blade
  swing.prev = blade
  const hits = physics.sweepCapsule(prev.a, prev.b, blade.a, blade.b, blade.radius, {
    ignore: attacker,
    filter: (node: Node, body: any) => isHurtbox(node, attacker, kind) || (bounces && blocksSwings(node, body)),
  }) as { node: Node; body: any; point: number[]; fraction: number }[]

  for (const h of hits) {
    if (bounces && blocksSwings(h.node, h.body)) {
      // A blocker reached before (or at the same moment as) every new target ends the swing here.
      result.blockedAt = h.point
      break
    }
    if (swing.hit.includes(h.node)) continue
    swing.hit.push(h.node)
    result.targets.push({ node: h.node, point: h.point })
  }
  // Targets the blade reached before the wall still take the hit; the ones after it are spared.
  return result
}
